    (1762000000001100001, 1762000000001000001, 1, 'java', 'package org.dromara.databus.script;\n\nimport lombok.extern.slf4j.Slf4j;\nimport org.dromara.common.core.exception.ServiceException;\nimport org.dromara.databus.component.DatabusNodeComponent;\nimport org.dromara.databus.component.schema.annotation.DatabusCmp;\nimport lombok.Data;\nimport org.dromara.databus.component.schema.annotation.DatabusProp;\nimport org.dromara.databus.component.schema.enums.ExprRole;\nimport org.dromara.databus.component.schema.enums.WidgetKind;\n\n\n\n/**\n * 变量赋值组件（注册名 {@code setValue}）。\n * <p>\n * 把 value 按参数约定解析（字面量，或 {@code {{ $.路径 }}} 整字段求值）后写入 path。\n * <p>\n * 同时镜像一份到节点 tag 命名空间（{@code $.<tag>.path} 与 {@code $.<tag>.value}），\n * 遵循"每个节点产出在自己 tag 下"的统一契约，供 {@link\n * org.dromara.databus.executor.NodeStepResultCollector} 按统一规则采集\n * 数据明细快照；用户配置的 path 写入不受影响。\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = "setValue",\n    name = "赋值",\n    icon = "ph:pencil-simple",\n    color = "#67c23a",\n    description = "把值（常量或 {{ $.路径 }} 表达式取值）写入上下文 $.数据空间.path",\n    sort = 10,\n    dataExample = """\n        {"path":"$.setValue1.demo","value":"常量 或 {{ $.入参路径 }}"}\n        """\n)\npublic class SetValueComponent extends DatabusNodeComponent {\n\n    @Override\n    public void process() {\n        SetValueCfg cfg = this.getCmpData(SetValueCfg.class);\n        if (cfg == null || cfg.getPath() == null || cfg.getPath().isBlank()) {\n            throw new ServiceException("赋值组件缺少 path 配置（tag=" + this.getTag() + "）");\n        }\n        Object resolved = resolveParam(cfg.getValue());\n        save(cfg.getPath(), resolved);\n\n        // 镜像到 tag 命名空间，供 collector 按统一契约采集节点产出快照\n        String tag = this.getTag();\n        if (tag != null && !tag.isBlank()) {\n            save("$." + tag + ".path", cfg.getPath());\n            save("$." + tag + ".value", resolved);\n        }\n\n        resultSummary("赋值：" + cfg.getPath());\n        log.debug("[databus] setValue 写入 path={}, tag={}", cfg.getPath(), this.getTag());\n    }\n\n    /**\n     * 变量赋值组件（setValue）的节点参数。\n     * <pre>\n     * { "path": "$.setValue1.userName", "value": "{{ $.httpRequest1.response.data.name }}" }\n     * </pre>\n     *\n     * @author databus\n     */\n    @Data\n    public static class SetValueCfg {\n\n        /**\n         * 写入目标 JSONPath（父路径不存在时自动创建）。\n         */\n        @DatabusProp(\n            label = "写入路径",\n            required = true,\n            exprRole = ExprRole.TARGET,\n            order = 1,\n            placeholder = "$.setValue1.userName",\n            description = "写入目标 JSONPath（父路径不存在自动创建），裸路径不求值"\n        )\n        private String path;\n\n        /**\n         * 写入值；字面量直接写入，动态值写 {@code {{ $.路径 }}} 由 resolve 求值（整字段保留原类型）。\n         */\n        @DatabusProp(\n            label = "写入值",\n            exprRole = ExprRole.DATA,\n            widget = WidgetKind.JSON,\n            order = 2,\n            placeholder = "常量 或 {{ $.入参路径 }}",\n            description = "字面量直接写入；动态值写 {{ $.路径 }}，整字段求值保留原类型。数字/布尔/对象字面量请用 JSON 高级模式"\n        )\n        private Object value;\n    }\n}\n', '初始迁移：内置 jar 件脚本化首版（seed 生成）', sysdate()),
    (1762000000001100002, 1762000000001000002, 1, 'java', 'package org.dromara.databus.script;\n\nimport lombok.extern.slf4j.Slf4j;\nimport org.dromara.common.core.exception.ServiceException;\nimport org.dromara.databus.component.DatabusNodeComponent;\nimport org.dromara.databus.component.schema.annotation.DatabusCmp;\nimport org.dromara.databus.context.PathResolver;\nimport java.util.ArrayList;\nimport java.util.List;\nimport lombok.Data;\nimport org.dromara.databus.component.schema.annotation.DatabusProp;\nimport org.dromara.databus.component.schema.enums.ExprRole;\nimport org.dromara.databus.component.schema.enums.WidgetKind;\n\n\n\n\n/**\n * 字段映射组件（注册名 {@code fieldMap}）。\n * <p>\n * 按 mappings 把上游字段逐条搬运到目标路径（平铺字段、原值复制，不做嵌套递归）。\n *\n * <p>支持两种搬运语义（见 {@link FieldMapCfg}）：\n * <ul>\n *   <li>单值搬运（默认，向后兼容）：from / to 均不含 {@code [*]}，原值搬运，\n *       不配 type 时行为完全等同改造前。</li>\n *   <li>数组批量搬运（A3 新增）：from / to 均含 {@code [*]}，逐元素读取、\n *       按索引写入目标数组的对应位置。</li>\n * </ul>\n *\n * <p>可选 {@code type} 转换：int / string / boolean / double，对每个搬运值\n * （含批量分支的每个元素）做转换，失败抛 {@link ServiceException}。\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = "fieldMap", name = "字段映射", icon = "ph:arrows-left-right", color = "#9c27b0",\n    description = "按 mappings 把 from 表达式（{{ $.路径 }}）取值逐条搬到 to 位置名（裸路径）；from/to 同时含 [*] 触发数组批量搬运，可选 type 做类型转换（int/string/boolean/double）", sort = 70,\n    dataExample = """\n        {"mappings":[{"from":"{{ $.httpRequest1.response.code }}","to":"$.fieldMap1.code","type":"int"},{"from":"{{ $.httpRequest1.response.data[*].NAME }}","to":"$.fieldMap1.items[*].name","type":"string"}]}\n        """\n)\npublic class FieldMapComponent extends DatabusNodeComponent {\n\n    @Override\n    public void process() {\n        FieldMapCfg cfg = this.getCmpData(FieldMapCfg.class);\n        if (cfg == null || cfg.getMappings() == null || cfg.getMappings().isEmpty()) {\n            throw new ServiceException("字段映射组件缺少 mappings 配置（tag=" + this.getTag() + "）");\n        }\n        int count = 0;\n        for (FieldMapCfg.Mapping mapping : cfg.getMappings()) {\n            if (mapping == null || mapping.getFrom() == null || mapping.getTo() == null) {\n                throw new ServiceException("字段映射条目缺少 from/to（tag=" + this.getTag() + "）");\n            }\n            String from = mapping.getFrom();\n            String to = mapping.getTo();\n            // from 为「要数据」字段：必须是整字段表达式 {{ $.路径 }}；to 为写目标名字，裸路径\n            String fromPath = PathResolver.wholeExpression(from);\n            if (fromPath == null) {\n                throw new ServiceException("字段映射条目 from 必须为 {{ $.路径 }} 形式（tag="\n                    + this.getTag() + "）：" + from);\n            }\n            boolean fromWildcard = fromPath.contains("[*]");\n            boolean toWildcard = to.contains("[*]");\n            if (fromWildcard && toWildcard) {\n                // 情况 a：数组批量搬运（A3 核心新能力）\n                count += batchMap(mapping, from, to);\n            } else if (fromWildcard) {\n                // 情况 b：from 含 [*] 但 to 不含\n                throw new ServiceException("字段映射条目 from 含 [*] 但 to 不含 [*]，无法批量写入（tag=" + this.getTag() + "）");\n            } else if (toWildcard) {\n                // 情况 c：to 含 [*] 但 from 不含\n                throw new ServiceException("字段映射条目 to 含 [*] 但 from 不含 [*]，无法批量写入（tag=" + this.getTag() + "）");\n            } else {\n                // 情况 d：单值搬运（resolve 取值，可选 type 转换）\n                Object value = resolveParam(from);\n                if (mapping.getType() != null && value != null) {\n                    value = convertType(value, mapping.getType());\n                }\n                save(to, value);\n                count++;\n            }\n        }\n        resultSummary("搬运 " + count + " 个字段");\n        log.debug("[databus] fieldMap 完成 {} 条映射，tag={}", count, this.getTag());\n    }\n\n    /**\n     * 数组批量搬运：from/to 均含 {@code [*]}，逐元素读取、按索引写入目标数组的对应位置。\n     *\n     * @param mapping 配置（含可选 type 转换）\n     * @param from   含 {@code [*]} 的源表达式（{@code {{ $.路径 [*] }}}）\n     * @param to     含 {@code [*]} 的目标路径（写目标名字，裸路径）\n     * @return 恒为 1\n     */\n    private int batchMap(FieldMapCfg.Mapping mapping, String from, String to) {\n        // 整字段表达式直接取列表；路径不存在时 resolve 抛错（不再静默跳过）\n        Object resolved = resolveParam(from);\n        if (!(resolved instanceof List<?> rawValues)) {\n            throw new ServiceException("字段映射批量源表达式未取到数组（tag="\n                + this.getTag() + "）：" + from + "，实际=" + resolved);\n        }\n        List<Object> values = new ArrayList<>();\n        rawValues.forEach(values::add);\n        for (int i = 0; i < values.size(); i++) {\n            Object value = values.get(i);\n            if (mapping.getType() != null) {\n                value = convertType(value, mapping.getType());\n            }\n            // 把 to 里的 [*] 替换为具体索引（如 $.target.items[*].name → $.target.items[0].name）\n            String targetPath = to.replace("[*]", "[" + i + "]");\n            save(targetPath, value);\n        }\n        log.debug("[databus] fieldMap 批量搬运 {} 个元素 from={} to={} tag={}",\n            values.size(), from, to, this.getTag());\n        return 1;\n    }\n\n    /**\n     * 类型转换：int / string / boolean / double。\n     * <p>value 为 null 时抛异常（不允许把 null 强转）；转换失败包装为 ServiceException。\n     *\n     * @param value 原值\n     * @param type  目标类型（int/string/boolean/double）\n     * @return 转换后的值\n     */\n    private Object convertType(Object value, String type) {\n        if (value == null) {\n            throw new ServiceException("fieldMap type 转换失败：value 为 null type=" + type);\n        }\n        try {\n            switch (type) {\n                case "int":\n                    return Integer.parseInt(value.toString());\n                case "string":\n                    return String.valueOf(value);\n                case "boolean":\n                    return Boolean.parseBoolean(value.toString());\n                case "double":\n                    return Double.parseDouble(value.toString());\n                default:\n                    throw new ServiceException("fieldMap 不支持的 type: " + type + "（支持 int/string/boolean/double）");\n            }\n        } catch (ServiceException e) {\n            throw e;\n        } catch (NumberFormatException e) {\n            throw new ServiceException("fieldMap type 转换失败 type=" + type + " value=" + value, e);\n        } catch (Exception e) {\n            throw new ServiceException("fieldMap type 转换失败 type=" + type + " value=" + value, e);\n        }\n    }\n\n    /**\n     * 字段映射组件（fieldMap）的节点参数。\n     * <pre>\n     * { "mappings": [ { "from": "{{ $.httpRequest1.response.data.captchaEnabled }}",\n     *                   "to":   "$.fieldMap1.captchaEnabled",\n     *                   "type": "boolean" } ] }\n     * </pre>\n     *\n     * <p>支持两种搬运语义：\n     * <ul>\n     *   <li>单值搬运（默认）：from 表达式（{@code {{ $.路径 }}}）不含 {@code [*]}，从 from 求单值原值写入 to。\n     *       <b>不配 type 时为原值搬运</b>。</li>\n     *   <li>数组批量搬运：from / to 均含 {@code [*]}（如 {@code {{ $.orders[*].NAME }}}\n     *       → {@code $.target.items[*].name}），from 求值得列表、逐元素按索引写入目标数组，\n     *       每个元素仍按单值处理（可叠加 type 转换）。</li>\n     * </ul>\n     *\n     * <p>{@code type} 可选，取值 {@code int / string / boolean / double}，空则原值搬运；\n     * 配置后对每个搬运值（含批量分支的每个元素）做类型转换，失败抛 {@link ServiceException}。\n     *\n     * @author databus\n     */\n    @Data\n    public static class FieldMapCfg {\n\n        /**\n         * 字段搬运条目列表：from 源表达式（要数据，{@code {{ $.路径 }}}）→ to 目标位置名（起名字，裸路径）。\n         */\n        @DatabusProp(label = "字段映射列表", required = true, order = 1)\n        private List<Mapping> mappings;\n\n        @Data\n        public static class Mapping {\n\n            /** 源表达式（{@code {{ $.路径 }}}）。含 {@code [*]}（与 to 同时含）时进入数组批量搬运。 */\n            @DatabusProp(\n                label = "源表达式 from", required = true, exprRole = ExprRole.DATA, order = 1,\n                description = "要数据：{{ $.路径 }}；与 to 同时含 [*] 时按数组逐元素搬运"\n            )\n            private String from;\n\n            /** 目标位置名（裸路径）。含 {@code [*]}（与 from 同时含）时进入数组批量搬运。 */\n            @DatabusProp(\n                label = "目标路径 to", required = true, exprRole = ExprRole.TARGET, order = 2,\n                placeholder = "$.数据空间.字段",\n                description = "起名字：裸写入路径，不求值"\n            )\n            private String to;\n\n            /**\n             * 目标类型转换（可选）。\n             * <p>取值 {@code int / string / boolean / double}，空则原值搬运。\n             * 配置后会对每个搬运值（含批量分支的每个元素）调用 convertType 转换，\n             * 失败抛 ServiceException。\n             */\n            @DatabusProp(\n                label = "类型转换 type", widget = WidgetKind.SELECT, order = 3,\n                description = "不选为原值搬运",\n                options = {\n                    @DatabusProp.Option(label = "整数 int", value = "int"),\n                    @DatabusProp.Option(label = "字符串 string", value = "string"),\n                    @DatabusProp.Option(label = "布尔 boolean", value = "boolean"),\n                    @DatabusProp.Option(label = "浮点 double", value = "double")\n                }\n            )\n            private String type;\n        }\n    }\n}\n', '初始迁移：内置 jar 件脚本化首版（seed 生成）', sysdate()),
    (1762000000001100003, 1762000000001000003, 1, 'java', 'package org.dromara.databus.script;\n\nimport lombok.extern.slf4j.Slf4j;\nimport org.dromara.common.core.exception.ServiceException;\nimport org.dromara.databus.component.DatabusNodeComponent;\nimport org.dromara.databus.component.schema.annotation.DatabusCmp;\nimport java.util.ArrayList;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.regex.Pattern;\nimport lombok.Data;\nimport org.dromara.databus.component.schema.annotation.DatabusProp;\nimport org.dromara.databus.component.schema.enums.ExprRole;\n\n\n\n\n/**\n * 数据补丁组件（注册名 {@code dataPatch}）。\n * <p>\n * 按 JSON Merge Patch 语义把补丁字段合并到 target 命中的每个对象：\n * 嵌套对象做深合并（保留目标已有兄弟键），叶子覆盖、缺失键新增，未声明字段原样保留。\n * 典型用途是 boQuery 查出记录后修改若干字段再交给 boUpdate 整体回写（查 → 改 → 写往返）。\n *\n * <p><b>实现机制（jayway 2.10.0 + Jackson provider 实测，勿改成拼叶子路径 set）：</b>\n * jayway {@code set} 只能改求值时已存在的属性节点，不创建缺失叶子/数组\n * （通配、过滤、空数组、缺失父路径均抛 PathNotFoundException）；而\n * {@code DatabusContext.write} 失败后的 createPath 兜底只认 {@code [数字]} 索引，\n * 不认 {@code [*]} / {@code [?(...)]}，拼通配叶子路径会写出字面垃圾键。\n * 故本组件不拼叶子路径，而是 read 出 target 命中的对象——Jackson provider 返回的\n * 是文档底层 {@code LinkedHashMap} 引用（filter/[*] 命中元素同为引用，已实测），\n * 直接在引用上递归 putAll，改动即文档本身；再用确定路径写 patchedCount。\n *\n * <p>零命中（路径不存在、过滤无结果、空数组）直接抛错，避免静默漏改。\n *\n * <p>命中对象数存入 {@code $.<tag>.patchedCount}。\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = "dataPatch", name = "数据补丁", icon = "ph:git-diff", color = "#009688",\n    description = "按 merge 语义把 patch 覆盖到 target 命中的每个对象（target 写目标裸路径，patch 叶子为常量或 {{ $.路径 }} 表达式）：[*] 全量/[i] 索引/[?(...)] 过滤均可，未声明字段（含 ID）保留、缺失字段新增；典型用于 boQuery 后改字段再交 boUpdate 回写，命中对象数写入 $.数据空间.patchedCount", sort = 80,\n    dataExample = """\n        {"target":"$.boQuery1.records[*]","patch":{"BO_FIELD_USER":"{{ $.request.newUser }}","BO_FIELD_NUM":99}}\n        """\n)\npublic class DataPatchComponent extends DatabusNodeComponent {\n\n    /** 补丁键（含嵌套层级）只接受安全标识符，拒绝点号/通配/表达式，杜绝歧义。 */\n    private static final Pattern SAFE_KEY = Pattern.compile("[A-Za-z_][A-Za-z0-9_]*");\n\n    @Override\n    public void process() {\n        DataPatchCfg cfg = this.getCmpData(DataPatchCfg.class);\n        if (cfg == null) {\n            throw new ServiceException("数据补丁组件缺少参数配置（tag=" + this.getTag() + "）");\n        }\n        String tag = this.getTag();\n        if (tag == null || tag.isBlank()) {\n            throw new ServiceException("数据补丁组件缺少数据空间标识（tag）");\n        }\n        if (cfg.getTarget() == null || cfg.getTarget().isBlank()) {\n            throw new ServiceException("数据补丁组件缺少 target 配置（tag=" + tag + "）");\n        }\n        if (cfg.getPatch() == null || cfg.getPatch().isEmpty()) {\n            throw new ServiceException("数据补丁组件缺少非空 patch 配置（tag=" + tag + "）");\n        }\n        String target = cfg.getTarget();\n\n        // 零命中 / 非对象目标直接报错（update 语义安全网）。read 返回底层 Map 引用。\n        Object hit = getOptional(target);\n        List<Map<String, Object>> targets = new ArrayList<>();\n        if (hit instanceof Map<?, ?> map) {\n            targets.add(asObjMap(map, target, tag));\n        } else if (hit instanceof List<?> list) {\n            if (list.isEmpty()) {\n                throw new ServiceException("数据补丁目标为空数组，没有可打补丁的记录: " + target);\n            }\n            for (int i = 0; i < list.size(); i++) {\n                Object el = list.get(i);\n                if (!(el instanceof Map<?, ?>)) {\n                    throw new ServiceException("数据补丁 target 命中的数组元素不是对象: " + target + "[" + i + "]");\n                }\n                targets.add(asObjMap((Map<?, ?>) el, target + "[" + i + "]", tag));\n            }\n        } else if (hit == null) {\n            throw new ServiceException("数据补丁目标无命中（路径不存在或过滤无结果）: " + target);\n        } else {\n            throw new ServiceException("数据补丁 target 必须指向对象或对象数组，实际为: "\n                + hit.getClass().getSimpleName() + "（" + target + "）");\n        }\n\n        // 在每个命中对象的引用上做深合并（引用即文档，putAll 直接生效，支持新增缺失键）\n        for (Map<String, Object> obj : targets) {\n            deepMerge(obj, cfg.getPatch(), target, tag);\n        }\n\n        save("$." + tag + ".patchedCount", targets.size());\n        resultSummary("补丁命中 " + targets.size() + " 个对象，合并 " + cfg.getPatch().size() + " 个字段");\n        log.info("[databus] dataPatch 完成 tag={} target={} 命中 {} 个对象，补丁 {} 个顶层字段",\n            tag, target, targets.size(), cfg.getPatch().size());\n    }\n\n    /**\n     * 递归深合并补丁到目标对象引用：\n     * <ul>\n     *   <li>补丁值是 Map → 目标同键已是 Map 则下钻合并，否则新建空 Map 后合并（支持新增嵌套结构）；</li>\n     *   <li>其余类型（字面量/{@code {{ $.路径 }}} 表达式/数组/null）→ resolveParam 后整体覆盖叶子。</li>\n     * </ul>\n     *\n     * @param dst    目标对象（文档底层 Map 引用）\n     * @param patch  当前层补丁\n     * @param target 根 target 路径（仅用于错误信息）\n     * @param tag    组件数据空间标识（仅用于错误信息）\n     */\n    @SuppressWarnings("unchecked")\n    private void deepMerge(Map<String, Object> dst, Map<String, Object> patch, String target, String tag) {\n        for (Map.Entry<String, Object> entry : patch.entrySet()) {\n            String key = entry.getKey();\n            if (key == null || !SAFE_KEY.matcher(key).matches()) {\n                throw new ServiceException("数据补丁字段名非法（只允许字母/数字/下划线且数字不开头）: "\n                    + key + "（tag=" + tag + "）");\n            }\n            Object value = entry.getValue();\n            if (value instanceof Map<?, ?> subPatch) {\n                Object existing = dst.get(key);\n                Map<String, Object> child;\n                if (existing instanceof Map<?, ?> existingMap) {\n                    child = (Map<String, Object>) existingMap;\n                } else {\n                    child = new LinkedHashMap<>();\n                    dst.put(key, child);\n                }\n                deepMerge(child, (Map<String, Object>) subPatch, target, tag);\n            } else {\n                dst.put(key, resolveParam(value));\n            }\n        }\n    }\n\n    /** 把命中的 Map 收窄为 {@code Map<String,Object>}，键非 String 直接报错。 */\n    @SuppressWarnings("unchecked")\n    private Map<String, Object> asObjMap(Map<?, ?> map, String where, String tag) {\n        for (Object k : map.keySet()) {\n            if (!(k instanceof String)) {\n                throw new ServiceException("数据补丁目标对象含非字符串键，无法合并: " + where + "（tag=" + tag + "）");\n            }\n        }\n        return (Map<String, Object>) map;\n    }\n\n    /**\n     * 数据补丁组件（dataPatch）的节点参数。\n     * <pre>\n     * { "target": "$.boQuery1.records[*]",\n     *   "patch": { "BO_FIELD_USER": "{{ $.request.newUser }}", "BO_FIELD_NUM": 99 } }\n     * </pre>\n     *\n     * <p>语义为 JSON Merge Patch：把 {@code patch} 中声明的字段合并到 {@code target}\n     * 命中的每个对象上，未声明的字段（如 BO 记录的 ID）原样保留；目标对象缺少的\n     * 字段自动新增，嵌套对象做深合并。\n     *\n     * <ul>\n     *   <li>{@code target} 为完整 JSONPath，支持 {@code [*]} 全量、{@code [i]} 索引、\n     *       {@code [?(...)]} 过滤（组件 read 出命中的对象引用后逐个深合并），\n     *       必须指向对象或对象数组。</li>\n     *   <li>{@code patch} 为补丁对象：键是相对 target 的字段名，支持嵌套对象\n     *       （递归深合并）；叶子值为字面量或 {@code {{ $.路径 }}} 表达式（resolve 求值），\n     *       数组作为整体叶子值写入。</li>\n     * </ul>\n     *\n     * @author databus\n     */\n    @Data\n    public static class DataPatchCfg {\n\n        /**\n         * 补丁目标 JSONPath（必填），指向待打补丁的对象或对象数组。\n         */\n        @DatabusProp(\n            label = "补丁目标路径", required = true, exprRole = ExprRole.TARGET, order = 1,\n            placeholder = "$.数据空间.records[*]",\n            description = "完整 JSONPath：[*] 全量 / [i] 索引 / [?(...)] 过滤，必须指向对象或对象数组"\n        )\n        private String target;\n\n        /**\n         * merge 补丁对象（必填，非空）：键为字段名（支持嵌套），叶子值为字面量或 {@code {{ $.路径 }}} 表达式。\n         */\n        @DatabusProp(\n            label = "补丁内容", required = true, valueExprRole = ExprRole.DATA, order = 2,\n            description = "键＝字段名；值为常量或 {{ $.路径 }} 表达式，数字/布尔/嵌套对象请切 JSON 高级模式；未声明字段保留"\n        )\n        private Map<String, Object> patch;\n    }\n}\n', '初始迁移：内置 jar 件脚本化首版（seed 生成）', sysdate()),
    (1762000000001100004, 1762000000001000004, 1, 'java', 'package org.dromara.databus.script;\n\nimport lombok.extern.slf4j.Slf4j;\nimport org.dromara.databus.component.DatabusNodeComponent;\nimport org.dromara.databus.component.schema.annotation.DatabusCmp;\nimport lombok.Data;\nimport org.dromara.databus.component.schema.annotation.DatabusProp;\nimport org.dromara.databus.component.schema.enums.ExprRole;\nimport org.dromara.databus.component.schema.enums.WidgetKind;\n\n\n\n/**\n * 响应组装组件（注册名 {@code response}）。\n * <p>\n * 链路的标准出口：把执行结果统一写入上下文固定位置\n * {@code $.response.result}（布尔）、{@code $.response.msg}（字符串）、\n * {@code $.response.data}（dataPath 指向的数据，缺省为 null）。\n * <p>\n * 同时镜像一份到节点 tag 命名空间（{@code $.<tag>.result/msg/data}），\n * 遵循"每个节点产出在自己 tag 下"的统一契约，供 {@link\n * org.dromara.databus.executor.NodeStepResultCollector} 按统一规则采集\n * 数据明细快照；{@code $.response.*} 仍是链路总响应出口，不受影响。\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = "response", name = "流程响应", icon = "ph:flag-checkered", color = "#f56c6c",\n    description = "设置链路返回结果，固定写入 $.response.result/msg/data", sort = 90,\n    dataExample = """\n        {"result":true,"msg":"成功","dataPath":"{{ $.fieldMap1 }}"}\n        """\n)\npublic class ResponseComponent extends DatabusNodeComponent {\n\n    @Override\n    public void process() {\n        ResponseCfg cfg = this.getCmpData(ResponseCfg.class);\n\n        Object resolvedResult = resolveParam(cfg == null ? null : cfg.getResult());\n        boolean success = toBoolean(resolvedResult);\n        Object resolvedMsg = resolveParam(cfg == null ? null : cfg.getMsg());\n        String msgText = resolvedMsg == null ? null : resolvedMsg.toString();\n\n        save("$.response.result", success);\n        save("$.response.msg", msgText);\n\n        // dataPath 为「要数据」字段：{{ $.路径 }} 由 resolve 取值（路径不存在抛错）\n        Object data = null;\n        if (cfg != null && cfg.getDataPath() != null && !cfg.getDataPath().isBlank()) {\n            data = resolveParam(cfg.getDataPath());\n        }\n        save("$.response.data", data);\n\n        // 镜像到 tag 命名空间，供 collector 按统一契约采集节点产出快照\n        String tag = this.getTag();\n        if (tag != null && !tag.isBlank()) {\n            String prefix = "$." + tag + ".";\n            save(prefix + "result", success);\n            save(prefix + "msg", msgText);\n            save(prefix + "data", data);\n        }\n        // 成败表格列已有，只有业务消息 msg 是增量信息；无 msg 不写，前端兜底「完成」\n        if (msgText != null && !msgText.isBlank()) {\n            resultSummary(msgText);\n        }\n        log.debug("[databus] response 组装完成 success={}, tag={}", success, this.getTag());\n    }\n\n    /**\n     * 布尔宽容转换：真正的 Boolean 直接取；其他类型按字符串 "true" 判定；null 为 false。\n     */\n    private boolean toBoolean(Object value) {\n        if (value instanceof Boolean b) {\n            return b;\n        }\n        return value != null && Boolean.parseBoolean(value.toString());\n    }\n\n    /**\n     * 响应组装组件（response）的节点参数。\n     * <pre>\n     * { "result": true, "msg": "{{ $.httpRequest1.response.msg }}", "dataPath": "{{ $.fieldMap1 }}" }\n     * </pre>\n     *\n     * @author databus\n     */\n    @Data\n    public static class ResponseCfg {\n\n        /**\n         * 执行结果：布尔字面量，或解析后为布尔/布尔字符串的路径。\n         */\n        @DatabusProp(\n            label = "执行结果", widget = WidgetKind.JSON, exprRole = ExprRole.DATA, order = 1,\n            placeholder = "true 或 {{ $.路径 }}",\n            description = "链路成功/失败：布尔字面量，或求值结果为布尔/布尔字符串的 {{ $.路径 }}；不填默认 true"\n        )\n        private Object result;\n\n        /**\n         * 提示信息：字面量，或 {@code {{ $.路径 }}} 表达式。\n         */\n        @DatabusProp(\n            label = "提示信息", widget = WidgetKind.JSON, exprRole = ExprRole.DATA, order = 2,\n            placeholder = "字面量 或 {{ $.路径 }}",\n            description = "返回给调用方的 msg，可嵌 {{ $.路径 }} 表达式"\n        )\n        private Object msg;\n\n        /**\n         * 返回数据所在的表达式（{@code {{ $.路径 }}}，整字段求值保留原类型）；不填则 data 为 null。\n         */\n        @DatabusProp(\n            label = "返回数据路径", exprRole = ExprRole.DATA, order = 3,\n            placeholder = "{{ $.数据空间.数据对象 }}",\n            description = "整字段求值后作为响应 data；不填则 data 为 null"\n        )\n        private String dataPath;\n    }\n}\n', '初始迁移：内置 jar 件脚本化首版（seed 生成）', sysdate()),
    (1762000000001100005, 1762000000001000005, 1, 'java', 'package org.dromara.databus.script;\n\nimport com.yomahub.liteflow.core.NodeBooleanComponent;\nimport lombok.extern.slf4j.Slf4j;\nimport org.dromara.common.core.exception.ServiceException;\nimport org.dromara.databus.component.schema.annotation.DatabusCmp;\nimport org.dromara.databus.component.schema.enums.NodeTypeKind;\nimport org.dromara.databus.context.DatabusContext;\nimport java.math.BigDecimal;\nimport java.util.Collection;\nimport java.util.Objects;\nimport lombok.Data;\nimport org.dromara.databus.component.schema.annotation.DatabusProp;\nimport org.dromara.databus.component.schema.enums.ExprRole;\nimport org.dromara.databus.component.schema.enums.WidgetKind;\n\n\n\n\n/**\n * 条件判断组件（注册名 {@code condition}）。\n * <p>\n * 布尔组件，作为 IF / WHILE 的条件位使用。按节点参数 {@link ConditionCfg} 中的\n * path/op/value 对上下文数据做比较，{@link #processBoolean()} 返回判断结果。\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = "condition", name = "条件判断", icon = "ph:equals", color = "#e6a23c",\n    description = "布尔条件：按 {{ $.路径 }} 表达式与比较符求值，供 IF/WHILE 条件槽使用",\n    nodeType = NodeTypeKind.BOOLEAN, sort = 30,\n    dataExample = """\n        {"path":"{{ $.httpRequest1.response.code }}","op":"eq","value":200}\n        """\n)\npublic class ConditionComponent extends NodeBooleanComponent {\n\n    @Override\n    public boolean processBoolean() {\n        ConditionCfg cfg = this.getCmpData(ConditionCfg.class);\n        if (cfg == null || cfg.getOp() == null) {\n            throw new ServiceException("条件组件缺少 op 配置（tag=" + this.getTag() + "）");\n        }\n        DatabusContext ctx = this.getContextBean(DatabusContext.class);\n        // path 为「要数据」字段：{{ $.路径 }} 由 resolve 取值（路径不存在抛错）\n        Object actual = cfg.getPath() == null ? null : ctx.resolve(cfg.getPath());\n        Object expected = ctx.resolve(cfg.getValue());\n\n        String op = cfg.getOp().trim();\n        return switch (op) {\n            case "isTrue" -> toBoolean(actual);\n            case "isNull" -> actual == null;\n            case "notBlank" -> actual != null && !actual.toString().isBlank();\n            case "eq" -> equalsValue(actual, expected);\n            case "ne" -> !equalsValue(actual, expected);\n            case "gt" -> compareNumber(actual, expected) > 0;\n            case "ge" -> compareNumber(actual, expected) >= 0;\n            case "lt" -> compareNumber(actual, expected) < 0;\n            case "le" -> compareNumber(actual, expected) <= 0;\n            case "contains" -> containsValue(actual, expected);\n            default -> throw new ServiceException("不支持的条件操作符: " + cfg.getOp());\n        };\n    }\n\n    /**\n     * 布尔宽容转换：真正的 Boolean 直接取；其他类型按字符串 "true" 判定。\n     */\n    private boolean toBoolean(Object value) {\n        if (value instanceof Boolean b) {\n            return b;\n        }\n        return value != null && Boolean.parseBoolean(value.toString());\n    }\n\n    /**\n     * 相等判断：两个数字按数值比较（避免 Integer 200 与 Long 200 不相等），其余走 Objects.equals。\n     */\n    private boolean equalsValue(Object actual, Object expected) {\n        if (actual instanceof Number a && expected instanceof Number b) {\n            return new BigDecimal(a.toString()).compareTo(new BigDecimal(b.toString())) == 0;\n        }\n        return Objects.equals(actual, expected);\n    }\n\n    /**\n     * 数值大小比较；任一侧不是数字时抛异常（节点失败，便于在试运行中暴露配置错误）。\n     */\n    private int compareNumber(Object actual, Object expected) {\n        if (!(actual instanceof Number) || !(expected instanceof Number)) {\n            throw new ServiceException("大小比较要求两侧都是数字，实际值=" + actual + "，比较值=" + expected);\n        }\n        return new BigDecimal(actual.toString()).compareTo(new BigDecimal(expected.toString()));\n    }\n\n    /**\n     * 包含判断：左值为集合时判断元素归属，否则按字符串包含处理。\n     */\n    private boolean containsValue(Object actual, Object expected) {\n        if (actual instanceof Collection<?> collection) {\n            return collection.contains(expected);\n        }\n        return actual != null && expected != null && actual.toString().contains(expected.toString());\n    }\n\n    /**\n     * 条件判断组件（condition）的节点参数。\n     * <p>\n     * 画布以裸 JSON 配置，对应 EL 中节点的 {@code .data("...")}：\n     * <pre>\n     * { "path": "{{ $.httpRequest1.response.code }}", "op": "eq", "value": 200 }\n     * </pre>\n     *\n     * @author databus\n     */\n    @Data\n    public static class ConditionCfg {\n\n        /**\n         * 左操作数表达式（要数据，{@code {{ $.路径 }}}，resolve 求值）。\n         */\n        @DatabusProp(\n            label = "左值表达式", required = true, exprRole = ExprRole.DATA, order = 1,\n            placeholder = "{{ $.路径 }}",\n            description = "取要判断的值：{{ $.数据空间.字段 }}"\n        )\n        private String path;\n\n        /**\n         * 比较操作符：isTrue / isNull / notBlank / eq / ne / gt / ge / lt / le / contains。\n         */\n        @DatabusProp(\n            label = "比较符", required = true, widget = WidgetKind.SELECT, order = 2,\n            options = {\n                @DatabusProp.Option(label = "为真 isTrue", value = "isTrue"),\n                @DatabusProp.Option(label = "为空 isNull", value = "isNull"),\n                @DatabusProp.Option(label = "非空白 notBlank", value = "notBlank"),\n                @DatabusProp.Option(label = "等于 eq", value = "eq"),\n                @DatabusProp.Option(label = "不等于 ne", value = "ne"),\n                @DatabusProp.Option(label = "大于 gt", value = "gt"),\n                @DatabusProp.Option(label = "大于等于 ge", value = "ge"),\n                @DatabusProp.Option(label = "小于 lt", value = "lt"),\n                @DatabusProp.Option(label = "小于等于 le", value = "le"),\n                @DatabusProp.Option(label = "包含 contains", value = "contains")\n            }\n        )\n        private String op;\n\n        /**\n         * 右操作数；字面量或 {@code {{ $.路径 }}} 表达式，执行前经 resolve 解析。\n         * isNull / isTrue / notBlank 时可不填。\n         */\n        @DatabusProp(\n            label = "右值", widget = WidgetKind.JSON, exprRole = ExprRole.DATA, order = 3,\n            placeholder = "200 或 {{ $.路径 }}",\n            description = "eq/ne/gt/ge/lt/le/contains 时填写；常量或 {{ $.路径 }} 表达式，数字/布尔请用 JSON 高级模式"\n        )\n        private Object value;\n    }\n}\n', '初始迁移：内置 jar 件脚本化首版（seed 生成）', sysdate()),
    (1762000000001100006, 1762000000001000006, 1, 'java', 'package org.dromara.databus.script;\n\nimport com.jayway.jsonpath.PathNotFoundException;\nimport lombok.extern.slf4j.Slf4j;\nimport org.dromara.common.core.exception.ServiceException;\nimport org.dromara.databus.component.DatabusNodeComponent;\nimport org.dromara.databus.component.schema.annotation.DatabusCmp;\nimport org.dromara.databus.context.DatabusContext;\nimport org.dromara.databus.context.JsonCodec;\nimport org.springframework.http.HttpHeaders;\nimport org.springframework.http.HttpMethod;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.client.ClientHttpResponse;\nimport org.springframework.http.client.JdkClientHttpRequestFactory;\nimport org.springframework.util.StreamUtils;\nimport org.springframework.util.StringUtils;\nimport org.springframework.web.client.ResourceAccessException;\nimport org.springframework.web.client.RestClient;\nimport org.springframework.web.util.UriComponentsBuilder;\nimport java.net.URI;\nimport java.net.http.HttpClient;\nimport java.nio.charset.Charset;\nimport java.nio.charset.StandardCharsets;\nimport java.time.Duration;\nimport java.util.ArrayList;\nimport java.util.Base64;\nimport java.util.Collection;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Locale;\nimport java.util.Map;\nimport java.util.Set;\nimport java.util.concurrent.ConcurrentHashMap;\nimport java.util.regex.Matcher;\nimport java.util.regex.Pattern;\nimport lombok.Data;\nimport org.dromara.databus.component.schema.annotation.DatabusProp;\nimport org.dromara.databus.component.schema.enums.ExprRole;\nimport org.dromara.databus.component.schema.enums.WidgetKind;\nimport org.dromara.databus.component.protocol.HttpBodyStrategy;\nimport org.dromara.databus.component.protocol.JsonBodyStrategy;\nimport org.dromara.databus.component.protocol.FormBodyStrategy;\nimport org.dromara.databus.component.protocol.RawBodyStrategy;\n\n\n\n\n/**\n * HTTP 请求组件（注册名 {@code httpRequest}）。\n * <p>\n * 单组件承载全部通用 HTTP 能力（method/bodyType 参数化，不按动词或媒介拆件），\n * 完整规格见 docs/wiki/databus-http-component.md：\n * <ul>\n *   <li>method：GET/POST/PUT/PATCH/DELETE；bodyType：none/json/form/raw（策略类序列化）；</li>\n *   <li>query 支持同名多值，headers/query/body/auth 值支持字面量与 {@code {{ $.路径 }}} 表达式解析；</li>\n *   <li>auth：none/basic（自动 Base64）/bearer（自动拼前缀）；</li>\n *   <li>出口：固定写 {@code $.<tag>.status} 与 {@code $.<tag>.response}，\n *       响应头按白名单写 {@code $.<tag>.headers.*}，mappings 默认 required；</li>\n *   <li>4xx/5xx 默认抛带全量上下文的 ServiceException，failOnHttpError=false 可容错落盘；</li>\n *   <li>timeoutMs 单值（默认 10s），RestClient 按超时分键缓存，默认跟随 3xx；不做重试。</li>\n * </ul>\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = "httpRequest", name = "Http 请求", icon = "ph:globe", color = "#409eff",\n    description = "通用 HTTP：GET/POST/PUT/PATCH/DELETE，JSON/表单/raw 三种请求体，basic/bearer 鉴权；状态码与响应存入 $.数据空间.status/response，mappings 抽取字段", sort = 20,\n    dataExample = """\n        {"method":"POST","url":"http://localhost:8080/api/login","headers":{"X-Tenant":"default"},"query":{"ids":["{{ $.id1 }}","{{ $.id2 }}"]},"bodyType":"json","body":{"username":"admin","password":"{{ $.pwd }}"},"rawContentType":"text/plain","auth":{"type":"bearer","token":"{{ $.login.token }}"},"timeoutMs":10000,"failOnHttpError":true,"responseCharset":"UTF-8","responseHeaders":["X-Total-Count"],"mappings":[{"field":"bizCode","path":"{{ $.code }}","required":true}]}\n        """\n)\npublic class HttpRequestComponent extends DatabusNodeComponent {\n\n    private static final long DEFAULT_TIMEOUT_MS = 10_000L;\n    private static final int LOG_EXCERPT_LEN = 500;\n    private static final Set<String> SUPPORTED_METHODS = Set.of("GET", "POST", "PUT", "PATCH", "DELETE");\n    private static final Set<String> SUPPORTED_BODY_TYPES = Set.of("none", "json", "form", "raw");\n    private static final Set<String> RESERVED_FIELDS = Set.of("status", "response", "headers");\n    private static final Set<String> SUPPORTED_AUTH = Set.of("none", "basic", "bearer");\n\n    /**\n     * 按 timeoutMs 分键缓存 RestClient——HttpClient 建造重且带连接池/线程，不可每请求新建。\n     */\n    private static final Map<Long, RestClient> CLIENT_CACHE = new ConcurrentHashMap<>();\n\n    private static final Map<String, HttpBodyStrategy> BODY_STRATEGIES = Map.of(\n        "json", new JsonBodyStrategy(),\n        "form", new FormBodyStrategy(),\n        "raw", new RawBodyStrategy()\n    );\n\n    /** 日志脱敏：key 命中即掩码（query 正则同步使用）。 */\n    private static final Pattern SENSITIVE_KEY_PATTERN =\n        Pattern.compile("(?i).*(password|passwd|token|secret|authorization|authCode|apiKey).*");\n    private static final Pattern SENSITIVE_QUERY_PATTERN =\n        Pattern.compile("(?i)([?&](?:password|passwd|token|secret|apikey|api_key)=)[^&]*");\n\n    @Override\n    public void process() {\n        HttpRequestCfg cfg = this.getCmpData(HttpRequestCfg.class);\n        String tag = this.getTag();\n        if (cfg == null || !StringUtils.hasText(cfg.getUrl())) {\n            throw new ServiceException("HTTP 组件缺少 url 配置（tag=" + tag + "）");\n        }\n        if (!StringUtils.hasText(tag)) {\n            throw new ServiceException("HTTP 组件缺少数据空间标识（tag）");\n        }\n        DatabusContext ctx = getDatabusContext();\n\n        String method = normalize(cfg.getMethod(), "GET").toUpperCase(Locale.ROOT);\n        if (!SUPPORTED_METHODS.contains(method)) {\n            throw new ServiceException("HTTP 组件不支持的 method: " + method + "（tag=" + tag + "）");\n        }\n        String bodyType = normalize(cfg.getBodyType(), "none").toLowerCase(Locale.ROOT);\n        if (!SUPPORTED_BODY_TYPES.contains(bodyType)) {\n            throw new ServiceException("HTTP 组件不支持的 bodyType: " + bodyType + "（tag=" + tag + "）");\n        }\n        long timeoutMs = resolveTimeout(cfg.getTimeoutMs(), tag);\n        Charset explicitCharset = resolveExplicitCharset(cfg.getResponseCharset(), tag);\n        boolean failOnHttpError = !Boolean.FALSE.equals(cfg.getFailOnHttpError());\n\n        String url = String.valueOf(ctx.resolve(cfg.getUrl()));\n        if (!url.startsWith("http://") && !url.startsWith("https://")) {\n            throw new ServiceException("HTTP 组件 url 必须以 http:// 或 https:// 开头: " + url + "（tag=" + tag + "）");\n        }\n        URI uri = buildUri(url, cfg.getQuery(), ctx, tag);\n\n        Map<String, String> headers = resolveHeaders(cfg.getHeaders(), ctx, tag);\n        applyAuth(headers, cfg.getAuth(), ctx, tag);\n\n        RestClient client = getClient(timeoutMs);\n        RestClient.RequestBodySpec request = client.method(HttpMethod.valueOf(method)).uri(uri);\n        headers.forEach(request::header);\n\n        if ("none".equals(bodyType)) {\n            if (cfg.getBody() != null) {\n                log.warn("[databus] httpRequest bodyType=none，已配置的 body 将被忽略（tag={}）", tag);\n            }\n        } else {\n            Object resolvedBody = resolveDeep(cfg.getBody(), ctx);\n            HttpBodyStrategy.PreparedBody prepared =\n                BODY_STRATEGIES.get(bodyType).prepare(resolvedBody, cfg.getRawContentType(), tag);\n            request.contentType(prepared.contentType()).body(prepared.content());\n            // raw 体可能含任意敏感文本，不打原文只记长度；json/form 走 key 脱敏\n            Object logBody = "raw".equals(bodyType)\n                ? "[raw 长度 " + (resolvedBody instanceof String s ? s.length() : 0) + "]"\n                : maskForLog(resolvedBody);\n            log.info("[databus] httpRequest 请求: {} {} body={}", method, maskUrl(url), excerpt(logBody));\n        }\n\n        long start = System.currentTimeMillis();\n        HttpResult result;\n        try {\n            result = request.exchange((req, res) -> {\n                byte[] bytes = res.getBody() != null ? StreamUtils.copyToByteArray(res.getBody()) : new byte[0];\n                Charset charset = explicitCharset != null\n                    ? explicitCharset\n                    : resolveResponseCharset(res);\n                return new HttpResult(res.getStatusCode().value(), bytes, pickHeaders(cfg.getResponseHeaders(), res), charset);\n            });\n        } catch (ResourceAccessException e) {\n            String reason = e.getMostSpecificCause() != null && e.getMostSpecificCause().getMessage() != null\n                ? e.getMostSpecificCause().getMessage()\n                : e.getClass().getSimpleName();\n            throw new ServiceException("HTTP 请求网络异常: " + method + " " + maskUrl(url)\n                + "（tag=" + tag + "，原因: " + reason + "）", e);\n        }\n        long elapsed = System.currentTimeMillis() - start;\n\n        String text = result.body().length == 0 ? null : new String(result.body(), result.charset());\n        if (result.status() >= 400) {\n            String bodyExcerpt = text == null ? "<空响应体>" : excerpt(text);\n            if (failOnHttpError) {\n                log.warn("[databus] httpRequest 错误响应: {} {} status={} 耗时={}ms body={}",\n                    method, maskUrl(url), result.status(), elapsed, bodyExcerpt);\n                throw new ServiceException("HTTP 请求返回错误状态: " + method + " " + maskUrl(url)\n                    + " → " + result.status() + "（tag=" + tag + "），响应体: " + bodyExcerpt);\n            }\n            log.warn("[databus] httpRequest 容错模式落盘错误响应: {} {} status={} 耗时={}ms",\n                method, maskUrl(url), result.status(), elapsed);\n        }\n\n        Object parsed = JsonCodec.parse(text);\n        Object responseStore = text == null ? null : (parsed != null ? parsed : text);\n\n        save("$." + tag + ".status", result.status());\n        save("$." + tag + ".response", responseStore);\n        if (cfg.getResponseHeaders() != null && !cfg.getResponseHeaders().isEmpty()) {\n            save("$." + tag + ".headers", result.headers());\n        }\n        extractMappings(cfg.getMappings(), responseStore, tag);\n\n        // 摘要只报方法+状态码：成败、耗时表格列已有；响应字节数无行动意义，响应内容看抽屉快照\n        resultSummary(method + " " + result.status());\n\n        log.info("[databus] httpRequest 响应: {} {} status={} 耗时={}ms body={}",\n            method, maskUrl(url), result.status(), elapsed,\n            responseStore == null ? "<空响应体>" : excerpt(maskForLog(responseStore)));\n    }\n\n    // ── 配置解析 ──\n\n    private static String normalize(String value, String defaultValue) {\n        return StringUtils.hasText(value) ? value.trim() : defaultValue;\n    }\n\n    private static long resolveTimeout(Long timeoutMs, String tag) {\n        if (timeoutMs == null) {\n            return DEFAULT_TIMEOUT_MS;\n        }\n        if (timeoutMs <= 0) {\n            throw new ServiceException("HTTP 组件 timeoutMs 必须为正数: " + timeoutMs + "（tag=" + tag + "）");\n        }\n        return timeoutMs;\n    }\n\n    private static Charset resolveExplicitCharset(String charsetName, String tag) {\n        if (!StringUtils.hasText(charsetName)) {\n            return null;\n        }\n        try {\n            return Charset.forName(charsetName.trim());\n        } catch (Exception e) {\n            throw new ServiceException("HTTP 组件 responseCharset 非法: " + charsetName + "（tag=" + tag + "）", e);\n        }\n    }\n\n    private static Charset resolveResponseCharset(ClientHttpResponse res) {\n        MediaType contentType = res.getHeaders().getContentType();\n        if (contentType != null && contentType.getCharset() != null) {\n            return contentType.getCharset();\n        }\n        return StandardCharsets.UTF_8;\n    }\n\n    /**\n     * query 拼接收尾：Collection/数组 → 同名重复参数；对象值不可表达（配置错）；null 跳过。\n     */\n    private URI buildUri(String rawUrl, Map<String, Object> query, DatabusContext ctx, String tag) {\n        UriComponentsBuilder builder = UriComponentsBuilder.fromUriString(rawUrl);\n        if (query != null) {\n            query.forEach((key, value) -> {\n                Object resolved = value == null ? null : ctx.resolve(value);\n                if (resolved == null) {\n                    return;\n                }\n                if (resolved instanceof Map<?, ?>) {\n                    throw new ServiceException(\n                        "HTTP 组件 query 参数 " + key + " 的值不能是对象（tag=" + tag + "）");\n                }\n                if (resolved instanceof Collection<?> collection) {\n                    Object[] items = collection.stream().filter(item -> item != null).toArray();\n                    if (items.length > 0) {\n                        builder.queryParam(key, items);\n                    }\n                } else if (resolved.getClass().isArray()) {\n                    builder.queryParam(key, (Object[]) resolved);\n                } else {\n                    builder.queryParam(key, resolved);\n                }\n            });\n        }\n        try {\n            return builder.build().encode(StandardCharsets.UTF_8).toUri();\n        } catch (IllegalArgumentException e) {\n            throw new ServiceException("HTTP 组件 URL 非法: " + rawUrl + "（tag=" + tag + "）", e);\n        }\n    }\n\n    /**\n     * headers 全量解析：Collection 值逗号拼接，对象值配置错，null 跳过。\n     */\n    private Map<String, String> resolveHeaders(Map<String, Object> source, DatabusContext ctx, String tag) {\n        Map<String, String> result = new LinkedHashMap<>();\n        if (source == null) {\n            return result;\n        }\n        source.forEach((key, value) -> {\n            Object resolved = value == null ? null : ctx.resolve(value);\n            if (resolved == null) {\n                return;\n            }\n            if (resolved instanceof Map<?, ?>) {\n                throw new ServiceException(\n                    "HTTP 组件 header " + key + " 的值不能是对象（tag=" + tag + "）");\n            }\n            if (resolved instanceof Collection<?> collection) {\n                List<String> parts = new ArrayList<>(collection.size());\n                collection.forEach(item -> {\n                    if (item != null) {\n                        parts.add(String.valueOf(item));\n                    }\n                });\n                result.put(key, String.join(", ", parts));\n            } else if (resolved.getClass().isArray()) {\n                List<String> parts = new ArrayList<>();\n                for (Object item : (Object[]) resolved) {\n                    if (item != null) {\n                        parts.add(String.valueOf(item));\n                    }\n                }\n                result.put(key, String.join(", ", parts));\n            } else {\n                result.put(key, String.valueOf(resolved));\n            }\n        });\n        return result;\n    }\n\n    /**\n     * 应用鉴权：auth 与 headers 同名 Authorization 冲突时 auth 为准并 warn。\n     */\n    private void applyAuth(Map<String, String> headers, HttpRequestCfg.AuthCfg auth, DatabusContext ctx, String tag) {\n        String type = auth == null || !StringUtils.hasText(auth.getType())\n            ? "none"\n            : auth.getType().trim().toLowerCase(Locale.ROOT);\n        if (!SUPPORTED_AUTH.contains(type)) {\n            throw new ServiceException("HTTP 组件 auth.type 非法: " + type + "（tag=" + tag + "），可选 none/basic/bearer");\n        }\n        if ("none".equals(type)) {\n            return;\n        }\n        headers.keySet().removeIf(name -> {\n            if (HttpHeaders.AUTHORIZATION.equalsIgnoreCase(name)) {\n                log.warn("[databus] httpRequest 同时配置了 auth 与 headers.Authorization，以 auth 为准（tag={}）", tag);\n                return true;\n            }\n            return false;\n        });\n        if ("bearer".equals(type)) {\n            Object token = ctx.resolve(auth.getToken());\n            if (token == null || !StringUtils.hasText(String.valueOf(token))) {\n                throw new ServiceException("HTTP 组件 auth.type=bearer 但 token 为空（tag=" + tag + "）");\n            }\n            headers.put(HttpHeaders.AUTHORIZATION, "Bearer " + token);\n        } else {\n            Object username = ctx.resolve(auth.getUsername());\n            Object password = ctx.resolve(auth.getPassword());\n            if (username == null || password == null) {\n                throw new ServiceException("HTTP 组件 auth.type=basic 但 username/password 为空（tag=" + tag + "）");\n            }\n            String credentials = username + ":" + password;\n            headers.put(HttpHeaders.AUTHORIZATION,\n                "Basic " + Base64.getEncoder().encodeToString(credentials.getBytes(StandardCharsets.UTF_8)));\n        }\n    }\n\n    /**\n     * 递归解析 Map/List 内的字符串值（body 用）；Map/List 原样保持结构。\n     */\n    private Object resolveDeep(Object value, DatabusContext ctx) {\n        if (value instanceof Map<?, ?> map) {\n            Map<String, Object> result = new LinkedHashMap<>(map.size());\n            map.forEach((key, item) -> result.put(String.valueOf(key), resolveDeep(item, ctx)));\n            return result;\n        }\n        if (value instanceof List<?> list) {\n            List<Object> result = new ArrayList<>(list.size());\n            for (Object item : list) {\n                result.add(resolveDeep(item, ctx));\n            }\n            return result;\n        }\n        return value == null ? null : ctx.resolve(value);\n    }\n\n    /**\n     * 响应头白名单抽取（大小写不敏感匹配，落盘 key 统一小写）。\n     */\n    private static Map<String, String> pickHeaders(List<String> whitelist, ClientHttpResponse res) {\n        Map<String, String> picked = new LinkedHashMap<>();\n        if (whitelist == null || whitelist.isEmpty()) {\n            return picked;\n        }\n        for (String name : whitelist) {\n            if (StringUtils.hasText(name)) {\n                String value = res.getHeaders().getFirst(name);\n                if (value != null) {\n                    picked.put(name.trim().toLowerCase(Locale.ROOT), value);\n                }\n            }\n        }\n        return picked;\n    }\n\n    /**\n     * mappings 抽取：required 缺省 true，取不到/响应体为空直接抛错；field 禁用保留名。\n     */\n    private void extractMappings(List<HttpRequestCfg.MappingCfg> mappings, Object responseStore, String tag) {\n        if (mappings == null || mappings.isEmpty()) {\n            return;\n        }\n        DatabusContext responseCtx = DatabusContext.fromObject(responseStore);\n        for (HttpRequestCfg.MappingCfg mapping : mappings) {\n            String field = mapping.getField();\n            String path = mapping.getPath();\n            if (!StringUtils.hasText(field) || !StringUtils.hasText(path)) {\n                throw new ServiceException("HTTP 组件 mappings 每项必须配置 field 和 path（tag=" + tag + "）");\n            }\n            field = field.trim();\n            if (field.startsWith("$")) {\n                throw new ServiceException("HTTP 组件 mappings.field 只写字段名不要带 $. 前缀: " + field + "（tag=" + tag + "）");\n            }\n            String firstSegment = field.contains(".") ? field.substring(0, field.indexOf(\'.\')) : field;\n            if (RESERVED_FIELDS.contains(firstSegment)) {\n                throw new ServiceException("HTTP 组件 mappings.field 不能使用保留名 status/response/headers: "\n                    + field + "（tag=" + tag + "）");\n            }\n            boolean required = !Boolean.FALSE.equals(mapping.getRequired());\n            if (responseStore == null) {\n                if (required) {\n                    throw new ServiceException("HTTP 响应体为空，无法抽取字段 " + field\n                        + "（tag=" + tag + "，path=" + path + "）；非必须字段可配 required:false");\n                }\n                continue;\n            }\n            // mappings.path 为「要数据」字段（{{ $.code }}）；required:false 时路径缺失按 null 处理\n            Object value;\n            try {\n                value = responseCtx.resolve(path);\n            } catch (PathNotFoundException e) {\n                value = null;\n            }\n            if (value == null && required) {\n                throw new ServiceException("HTTP 响应缺少字段（路径不存在或值为 null）: path=" + path\n                    + " → field=" + field + "（tag=" + tag + "）；非必须字段可配 required:false。实际响应: "\n                    + excerpt(maskForLog(responseStore)));\n            }\n            save("$." + tag + "." + field, value);\n        }\n    }\n\n    // ── 基础设施 ──\n\n    /**\n     * 构造带超时与重定向跟随的 RestClient（JDK HttpClient：默认不跟随 3xx，显式开 NORMAL）。\n     */\n    private static RestClient getClient(long timeoutMs) {\n        return CLIENT_CACHE.computeIfAbsent(timeoutMs, ms -> {\n            HttpClient httpClient = HttpClient.newBuilder()\n                .connectTimeout(Duration.ofMillis(ms))\n                .followRedirects(HttpClient.Redirect.NORMAL)\n                .build();\n            JdkClientHttpRequestFactory factory = new JdkClientHttpRequestFactory(httpClient);\n            factory.setReadTimeout(Duration.ofMillis(ms));\n            return RestClient.builder().requestFactory(factory).build();\n        });\n    }\n\n    private static String maskUrl(String url) {\n        Matcher matcher = SENSITIVE_QUERY_PATTERN.matcher(url);\n        return matcher.replaceAll("$1***");\n    }\n\n    /**\n     * 日志脱敏：Map/List 递归把敏感 key 的值掩码，标量原样。\n     */\n    private static Object maskForLog(Object value) {\n        if (value instanceof Map<?, ?> map) {\n            Map<String, Object> masked = new LinkedHashMap<>(map.size());\n            map.forEach((key, item) -> {\n                String name = String.valueOf(key);\n                if (SENSITIVE_KEY_PATTERN.matcher(name).matches()) {\n                    masked.put(name, "***");\n                } else {\n                    masked.put(name, maskForLog(item));\n                }\n            });\n            return masked;\n        }\n        if (value instanceof List<?> list) {\n            List<Object> masked = new ArrayList<>(list.size());\n            list.forEach(item -> masked.add(maskForLog(item)));\n            return masked;\n        }\n        return value;\n    }\n\n    private static String excerpt(Object value) {\n        String text = value instanceof String s ? s : JsonCodec.toJson(value);\n        return text.length() <= LOG_EXCERPT_LEN ? text : text.substring(0, LOG_EXCERPT_LEN) + "...(截断)";\n    }\n\n    /**\n     * 一次 HTTP 调用的原始结果（exchange 内构造，charset 随响应头确定）。\n     */\n    private record HttpResult(int status, byte[] body, Map<String, String> headers, Charset charset) {\n    }\n\n    /**\n     * HTTP 请求组件（httpRequest）的节点参数。\n     * <pre>\n     * {\n     *   "method": "POST",\n     *   "url": "http://localhost:8080/auth/login",\n     *   "headers": { "X-Tenant": "default" },\n     *   "query":   { "ids": ["{{ $.id1 }}", "{{ $.id2 }}"] },\n     *   "bodyType": "json",\n     *   "body":    { "username": "admin", "password": "{{ $.pwd }}" },\n     *   "rawContentType": "text/plain",\n     *   "auth":    { "type": "bearer", "token": "{{ $.login.token }}" },\n     *   "timeoutMs": 10000,\n     *   "failOnHttpError": true,\n     *   "responseCharset": "UTF-8",\n     *   "responseHeaders": ["X-Total-Count"],\n     *   "mappings": [\n     *     { "field": "bizCode", "path": "{{ $.code }}", "required": true }\n     *   ]\n     * }\n     * </pre>\n     * 完整规格见 docs/wiki/databus-http-component.md：\n     * method 支持 GET/POST/PUT/PATCH/DELETE；bodyType 支持 none/json/form/raw；\n     * 不做 multipart/重试/代理/证书/OAuth2/HttpConnection。\n     *\n     * @author databus\n     */\n    @Data\n    public static class HttpRequestCfg {\n\n        /**\n         * 请求方法：GET/POST/PUT/PATCH/DELETE（缺省 GET）。\n         */\n        @DatabusProp(\n            label = "请求方法", widget = WidgetKind.SELECT, order = 1,\n            options = {\n                @DatabusProp.Option(label = "GET", value = "GET"),\n                @DatabusProp.Option(label = "POST", value = "POST"),\n                @DatabusProp.Option(label = "PUT", value = "PUT"),\n                @DatabusProp.Option(label = "PATCH", value = "PATCH"),\n                @DatabusProp.Option(label = "DELETE", value = "DELETE")\n            }\n        )\n        private String method;\n\n        /**\n         * 请求地址（必填），必须带 http(s) 协议前缀；支持嵌入表达式（如 {@code http://x/{{ $.userId }}/detail}）。\n         */\n        @DatabusProp(\n            label = "请求地址", required = true, exprRole = ExprRole.DATA, order = 2,\n            placeholder = "https://example.com/api/{{ $.路径 }}",\n            description = "必须带 http(s) 前缀；路径中可嵌 {{ $.路径 }} 表达式"\n        )\n        private String url;\n\n        /**\n         * 请求头：value 为字面量或 {@code {{ $.路径 }}} 表达式；Collection 值按逗号拼接。\n         * 与 {@link #auth} 生成的 Authorization 冲突时以 auth 为准（warn 并忽略此项）。\n         */\n        @DatabusProp(label = "请求头 headers", valueExprRole = ExprRole.DATA, order = 3)\n        private Map<String, Object> headers;\n\n        /**\n         * 查询参数：value 同上；Collection/数组值序列化为同名重复参数（ids=1&amp;ids=2），\n         * 对象值无法表达（配置错），null 值跳过。\n         */\n        @DatabusProp(label = "查询参数 query", valueExprRole = ExprRole.DATA, order = 4)\n        private Map<String, Object> query;\n\n        /**\n         * 请求体媒介：none（缺省）/ json / form / raw。\n         */\n        @DatabusProp(\n            label = "请求体类型", widget = WidgetKind.SELECT, order = 5,\n            options = {\n                @DatabusProp.Option(label = "无请求体 none", value = "none"),\n                @DatabusProp.Option(label = "JSON json", value = "json"),\n                @DatabusProp.Option(label = "表单 form", value = "form"),\n                @DatabusProp.Option(label = "原文 raw", value = "raw")\n            }\n        )\n        private String bodyType;\n\n        /**\n         * 请求体：内部字符串值发送前做路径解析（递归）。\n         * json：Map/List 序列化，字符串视为 JSON 原文；form：必须 Map，转 urlencoded；raw：必须字符串。\n         */\n        @DatabusProp(\n            label = "请求体 body", widget = WidgetKind.JSON, exprRole = ExprRole.DATA, order = 6,\n            description = "json：JSON 对象（内部字符串可写 {{ $.路径 }}）；form：键值对象；raw：字符串。复杂结构请用 JSON 高级模式",\n            showWhen = @DatabusProp.ShowWhen(field = "bodyType", ne = "none")\n        )\n        private Object body;\n\n        /**\n         * raw 媒介的 Content-Type（可含 charset），为空兜底 text/plain;charset=UTF-8。\n         */\n        @DatabusProp(\n            label = "raw Content-Type", order = 7, placeholder = "text/plain",\n            showWhen = @DatabusProp.ShowWhen(field = "bodyType", eq = "raw")\n        )\n        private String rawContentType;\n\n        /**\n         * 鉴权配置（缺省 type=none）。\n         */\n        @DatabusProp(label = "鉴权 auth", order = 8)\n        private AuthCfg auth;\n\n        /**\n         * 超时毫秒数，连接+读取合并控制（缺省 10000，必须为正数）。\n         */\n        @DatabusProp(label = "超时毫秒", order = 9)\n        private Long timeoutMs;\n\n        /**\n         * 4xx/5xx 是否直接抛错（缺省 true）；false 时错误响应也落数据空间交下游 condition 判断。\n         */\n        @DatabusProp(\n            label = "HTTP 错误直接抛错", widget = WidgetKind.BOOLEAN, order = 10,\n            description = "关闭后 4xx/5xx 也落数据空间，交下游 condition 件判断"\n        )\n        private Boolean failOnHttpError;\n\n        /**\n         * 强制响应字符集（如 GBK）；缺省按响应头 charset、再缺省 UTF-8。\n         */\n        @DatabusProp(label = "响应字符集", order = 11, placeholder = "UTF-8")\n        private String responseCharset;\n\n        /**\n         * 响应头白名单：点名的响应头抽到 {@code $.<tag>.headers.<名小写>}，缺省空数组不落任何头。\n         */\n        @DatabusProp(label = "响应头白名单", order = 12, description = "输入头名称后回车添加")\n        private List<String> responseHeaders;\n\n        /**\n         * 响应字段抽取：field=数据空间字段名，path=响应体 JSONPath，required 缺省 true。\n         */\n        @DatabusProp(label = "响应字段抽取 mappings", order = 13)\n        private List<MappingCfg> mappings;\n\n        /**\n         * 鉴权配置。\n         */\n        @Data\n        public static class AuthCfg {\n\n            /** none（缺省）/ basic / bearer。 */\n            @DatabusProp(\n                label = "鉴权方式", widget = WidgetKind.SELECT, order = 1,\n                options = {\n                    @DatabusProp.Option(label = "无 none", value = "none"),\n                    @DatabusProp.Option(label = "Basic", value = "basic"),\n                    @DatabusProp.Option(label = "Bearer Token", value = "bearer")\n                }\n            )\n            private String type;\n\n            /** basic 用户名（支持路径取值）。 */\n            @DatabusProp(\n                label = "用户名", widget = WidgetKind.JSON, exprRole = ExprRole.DATA, order = 2,\n                showWhen = @DatabusProp.ShowWhen(field = "type", eq = "basic")\n            )\n            private Object username;\n\n            /** basic 密码（支持路径取值），组件自动 Base64。 */\n            @DatabusProp(\n                label = "密码", widget = WidgetKind.JSON, exprRole = ExprRole.DATA, order = 3,\n                description = "可填 {{ $.路径 }} 表达式；组件自动 Base64",\n                showWhen = @DatabusProp.ShowWhen(field = "type", eq = "basic")\n            )\n            private Object password;\n\n            /** bearer 令牌（支持路径取值），组件自动拼 "Bearer " 前缀。 */\n            @DatabusProp(\n                label = "Token", widget = WidgetKind.JSON, exprRole = ExprRole.DATA, order = 4,\n                description = "可填 {{ $.路径 }} 表达式；组件自动拼 Bearer 前缀",\n                showWhen = @DatabusProp.ShowWhen(field = "type", eq = "bearer")\n            )\n            private Object token;\n        }\n\n        /**\n         * 响应字段抽取配置。\n         */\n        @Data\n        public static class MappingCfg {\n\n            /** 存入 {@code $.<tag>.} 下的字段名；禁止 status/response/headers 保留名。 */\n            @DatabusProp(label = "存为字段名", required = true, order = 1)\n            private String field;\n\n            /** 响应体内的取值表达式（{@code {{ $.code }}}）。 */\n            @DatabusProp(\n                label = "响应取值表达式", required = true, exprRole = ExprRole.DATA, order = 2,\n                placeholder = "{{ $.code }}"\n            )\n            private String path;\n\n            /** 取不到时是否抛错（缺省 true）。 */\n            @DatabusProp(label = "取不到则抛错", widget = WidgetKind.BOOLEAN, order = 3)\n            private Boolean required;\n        }\n    }\n}\n', '初始迁移：内置 jar 件脚本化首版（seed 生成）', sysdate()),
    (1762000000001100007, 1762000000001000007, 1, 'java', 'package org.dromara.databus.script;\n\nimport lombok.extern.slf4j.Slf4j;\nimport org.dromara.common.core.exception.ServiceException;\nimport org.dromara.common.core.utils.SpringUtils;\nimport org.dromara.databus.component.DatabusNodeComponent;\nimport org.dromara.databus.component.schema.annotation.DatabusCmp;\nimport org.dromara.databus.connector.Connection;\nimport org.dromara.databus.connector.bpm.BpmHttpConnector;\nimport org.dromara.databus.connector.bpm.dto.SessionCreateRequest;\nimport java.util.List;\nimport java.util.Map;\nimport lombok.Data;\nimport org.dromara.databus.component.schema.annotation.DatabusProp;\nimport org.dromara.databus.component.schema.enums.ExprRole;\nimport org.dromara.databus.component.schema.enums.WidgetKind;\n\n\n\n\n/**\n * SESSION_CREATE 组件（注册名 {@code sessionCreate}）。\n * <p>调 BPM 端 SESSION_CREATE 端点，创建 BPM 客户端会话。响应 {@code {sessionId, idCard}}\n * 按字段平铺写入数据空间 {@code $.<tag>.sessionId} / {@code $.<tag>.idCard}。\n *\n * <p>网关鉴权（/portal/openapi 签名）已在连接层完成；ipWhiteList 旧机制随 jd 通道删除，\n * 请求固定传空列表（不限制）。\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = "sessionCreate", name = "BPM 会话", shortName = "会话",\n    icon = "ph:sign-in", color = "#409eff",\n    description = "创建 BPM 会话（登录获取 sid），响应平铺到 $.数据空间", sort = 100,\n    dataExample = """\n        {"connectionId":"bpm-default","userName":"admin","password":"{{ $.request.password }}"}\n        """\n)\npublic class SessionCreateComponent extends DatabusNodeComponent {\n\n    private static final String DEFAULT_CLIENT_IP = "0.0.0.0";\n    private static final String DEFAULT_LANG = "cn";\n    private static final String DEFAULT_DEVICE = "PC";\n\n    @Override\n    public void process() {\n        SessionCreateCfg cfg = this.getCmpData(SessionCreateCfg.class);\n        if (cfg == null) {\n            throw new ServiceException("SESSION_CREATE 组件缺少参数配置（tag=" + this.getTag() + "）");\n        }\n        String tag = this.getTag();\n        if (tag == null || tag.isBlank()) {\n            throw new ServiceException("SESSION_CREATE 组件缺少数据空间标识（tag）");\n        }\n        if (cfg.getConnectionId() == null || cfg.getConnectionId().isBlank()) {\n            throw new ServiceException("SESSION_CREATE 组件缺少 connectionId 配置（tag=" + tag + "）");\n        }\n        if (cfg.getUserName() == null || cfg.getUserName().isBlank()) {\n            throw new ServiceException("SESSION_CREATE 组件缺少 userName 配置（tag=" + tag + "）");\n        }\n        if (cfg.getPassword() == null || cfg.getPassword().isBlank()) {\n            throw new ServiceException("SESSION_CREATE 组件缺少 password 配置（tag=" + tag + "）");\n        }\n\n        // 参数解析：字段经 resolve 求值（{{ $.路径 }} 或字面量）\n        String connectionId = resolveStr(cfg.getConnectionId());\n        String userName = resolveStr(cfg.getUserName());\n        String password = resolveStr(cfg.getPassword());\n        String clientIp = cfg.getClientIp() == null || cfg.getClientIp().isBlank()\n                ? DEFAULT_CLIENT_IP : resolveStr(cfg.getClientIp());\n        String lang = cfg.getLang() == null || cfg.getLang().isBlank()\n                ? DEFAULT_LANG : resolveStr(cfg.getLang());\n        String device = cfg.getDevice() == null || cfg.getDevice().isBlank()\n                ? DEFAULT_DEVICE : resolveStr(cfg.getDevice());\n\n        BpmHttpConnector connector = SpringUtils.getBean(BpmHttpConnector.class);\n        Connection conn = getDatabusContext().getConnection(connectionId);\n\n        SessionCreateRequest request = new SessionCreateRequest();\n        request.setUserName(userName);\n        request.setPassword(password);\n        request.setClientIp(clientIp);\n        request.setLang(lang);\n        request.setDevice(device);\n        // ipWhiteList 旧机制随 jd 免会话通道删除（网关签名鉴权已替代），固定空列表\n        request.setIpWhiteList(List.of());\n\n        Object result = connector.createSession(conn, request);\n        if (!(result instanceof Map<?, ?> resultMap)) {\n            throw new ServiceException("SESSION_CREATE 响应非 JSON 对象: " + result);\n        }\n        // 平铺 sessionId / idCard 到数据空间\n        resultMap.forEach((key, value) -> save("$." + tag + "." + key, value));\n        resultSummary("会话：" + resultMap.get("sessionId"));\n        log.info("[databus] sessionCreate 完成 tag={} sessionId={}", tag, resultMap.get("sessionId"));\n    }\n\n    /**\n     * 字符串参数解析：resolve 求值后统一转 String。\n     */\n    private String resolveStr(Object input) {\n        if (input == null) {\n            return null;\n        }\n        Object resolved = resolveParam(input);\n        return resolved == null ? null : resolved.toString();\n    }\n\n    /**\n     * SESSION_CREATE 组件（sessionCreate）的节点参数。\n     * <pre>\n     * {\n     *   "connectionId": "bpm-default",\n     *   "userName": "admin",\n     *   "password": "{{ $.request.password }}",\n     *   "clientIp": "0.0.0.0",\n     *   "lang": "cn",\n     *   "device": "PC"\n     * }\n     * </pre>\n     * 字符串字段支持字面量与 {@code {{ $.路径 }}} 表达式，组件解析后传入 BPM 端 SESSION_CREATE 端点。\n     * 网关签名鉴权（/portal/openapi）已在连接层完成；请求体 ipWhiteList 旧机制随 jd 通道删除，\n     * 组件固定传空列表，无需在此配置。\n     *\n     * @author databus\n     */\n    @Data\n    public static class SessionCreateCfg {\n\n        /** 连接实例 ID（必填），引用连接管理页配置的 BPM 连接 */\n        @DatabusProp(label = "连接", required = true, widget = WidgetKind.CONNECTION_SELECT, order = 1)\n        private String connectionId;\n\n        /** BPM 用户 ID（必填） */\n        @DatabusProp(label = "用户 ID", required = true, exprRole = ExprRole.DATA, order = 2)\n        private String userName;\n\n        /** 用户密码（必填） */\n        @DatabusProp(label = "密码", required = true, widget = WidgetKind.PASSWORD, exprRole = ExprRole.DATA, order = 3)\n        private String password;\n\n        /** 客户端真实 IP（可选，默认 0.0.0.0，BPM 端校验 IP 白名单时用） */\n        @DatabusProp(label = "客户端 IP", exprRole = ExprRole.DATA, order = 4, placeholder = "0.0.0.0")\n        private String clientIp;\n\n        /** 语言（可选，默认 cn） */\n        @DatabusProp(label = "语言", exprRole = ExprRole.DATA, order = 5, placeholder = "cn")\n        private String lang;\n\n        /** 设备类型（可选，默认 PC） */\n        @DatabusProp(label = "设备类型", exprRole = ExprRole.DATA, order = 6, placeholder = "PC")\n        private String device;\n    }\n}\n', '初始迁移：内置 jar 件脚本化首版（seed 生成）', sysdate()),
    (1762000000001100008, 1762000000001000008, 1, 'java', 'package org.dromara.databus.script;\n\nimport lombok.extern.slf4j.Slf4j;\nimport org.dromara.common.core.exception.ServiceException;\nimport org.dromara.common.core.utils.SpringUtils;\nimport org.dromara.databus.component.DatabusNodeComponent;\nimport org.dromara.databus.component.schema.annotation.DatabusCmp;\nimport org.dromara.databus.connector.Connection;\nimport org.dromara.databus.connector.bpm.BpmHttpConnector;\nimport org.dromara.databus.connector.bpm.dto.ProcessStartRequest;\nimport java.util.List;\nimport java.util.Map;\nimport lombok.Data;\nimport org.dromara.databus.component.schema.annotation.DatabusProp;\nimport org.dromara.databus.component.schema.enums.ExprRole;\nimport org.dromara.databus.component.schema.enums.WidgetKind;\n\n\n\n\n/**\n * PROCESS_START 组件（注册名 {@code processStart}）。\n * <p>\n * 调 BPM 端 PROCESS_START 端点启动流程。响应 {@code {processInstanceId, isProcess, activeTaskIds}}\n * 按字段平铺写入数据空间 {@code $.<tag>.*}。\n *\n * <p>title 含 {@code {{ $.xxx }}} 表达式时由本组件调 {@code getDatabusContext().resolveMixedPath(...)}\n * 求值拼接为字符串后传 BPM 端。BPM 端不做 autocomplete（决策 9.1.1：task_complete 独立端点）。\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = "processStart", name = "BPM 启流程", shortName = "启流程",\n    icon = "ph:rocket", color = "#e6a23c",\n    description = "启动 BPM 流程实例，title 支持 {{ $.xxx }} 表达式，响应平铺到 $.数据空间（含 processInstanceId 供下游 boCreate.bindId 引用）", sort = 110,\n    dataExample = """\n        {"connectionId":"bpm-default","processDefId":"proc-001","uid":"admin","title":"申请-{{ $.request.code }}"}\n        """\n)\npublic class ProcessStartComponent extends DatabusNodeComponent {\n\n    @Override\n    public void process() {\n        ProcessStartCfg cfg = this.getCmpData(ProcessStartCfg.class);\n        if (cfg == null) {\n            throw new ServiceException("PROCESS_START 组件缺少参数配置（tag=" + this.getTag() + "）");\n        }\n        String tag = this.getTag();\n        if (tag == null || tag.isBlank()) {\n            throw new ServiceException("PROCESS_START 组件缺少数据空间标识（tag）");\n        }\n        if (cfg.getConnectionId() == null || cfg.getConnectionId().isBlank()) {\n            throw new ServiceException("PROCESS_START 组件缺少 connectionId 配置（tag=" + tag + "）");\n        }\n        if (cfg.getProcessDefId() == null || cfg.getProcessDefId().isBlank()) {\n            throw new ServiceException("PROCESS_START 组件缺少 processDefId 配置（tag=" + tag + "）");\n        }\n        if (cfg.getUid() == null || cfg.getUid().isBlank()) {\n            throw new ServiceException("PROCESS_START 组件缺少 uid 配置（tag=" + tag + "）");\n        }\n        if (cfg.getTitle() == null || cfg.getTitle().isBlank()) {\n            throw new ServiceException("PROCESS_START 组件缺少 title 配置（tag=" + tag + "）");\n        }\n\n        // 参数解析：connectionId/processDefId/uid 经 resolve 求值（{{ $.路径 }} 或字面量）\n        String connectionId = resolveStr(cfg.getConnectionId());\n        String processDefId = resolveStr(cfg.getProcessDefId());\n        String uid = resolveStr(cfg.getUid());\n        // title 用 resolveMixedPath 求值 {{ }} 片段后拼接为字符串（无标记时原样）\n        String title = getDatabusContext().resolveMixedPath(cfg.getTitle());\n\n        BpmHttpConnector connector = SpringUtils.getBean(BpmHttpConnector.class);\n        Connection conn = getDatabusContext().getConnection(connectionId);\n\n        ProcessStartRequest request = new ProcessStartRequest();\n        request.setProcessDefId(processDefId);\n        request.setUid(uid);\n        request.setTitle(title);\n\n        Object result = connector.processStart(conn, request);\n        if (!(result instanceof Map<?, ?> resultMap)) {\n            throw new ServiceException("PROCESS_START 响应非 JSON 对象: " + result);\n        }\n        // 平铺 processInstanceId / isProcess / activeTaskIds\n        resultMap.forEach((key, value) -> save("$." + tag + "." + key, value));\n        Object activeTaskIds = resultMap.get("activeTaskIds");\n        String summaryText = "流程：" + resultMap.get("processInstanceId");\n        if (activeTaskIds instanceof List<?> tasks && !tasks.isEmpty()) {\n            summaryText += "，待办 " + tasks.size() + " 个";\n        }\n        resultSummary(summaryText);\n        log.info("[databus] processStart 完成 tag={} processInstanceId={} isProcess={}",\n                tag, resultMap.get("processInstanceId"), resultMap.get("isProcess"));\n    }\n\n    /**\n     * 字符串参数解析：resolve 求值后统一转 String。\n     */\n    private String resolveStr(Object input) {\n        if (input == null) {\n            return null;\n        }\n        Object resolved = resolveParam(input);\n        return resolved == null ? null : resolved.toString();\n    }\n\n    /**\n     * PROCESS_START 组件（processStart）的节点参数。\n     * <pre>\n     * {\n     *   "connectionId": "bpm-default",\n     *   "processDefId": "proc-001",          // 必填\n     *   "uid": "admin",                     // 必填\n     *   "title": "采购申请-{{ $.request.code }}" // 必填，支持 {{ $.xxx }} 表达式\n     * }\n     * </pre>\n     * title 含 {@code {{ $.xxx }}} 表达式时由组件调 {@code resolveMixedPath} 求值拼接为字符串后传入 BPM 端\n     * （模板替换在 Component 层完成，BPM 端只接收纯字符串）。\n     *\n     * @author databus\n     */\n    @Data\n    public static class ProcessStartCfg {\n\n        /** 连接实例 ID（必填） */\n        @DatabusProp(label = "连接", required = true, widget = WidgetKind.CONNECTION_SELECT, order = 1)\n        private String connectionId;\n\n        /** 流程定义 ID（必填） */\n        @DatabusProp(label = "流程定义 ID", required = true, order = 2)\n        private String processDefId;\n\n        /** 创建人用户 ID（必填，构造 UserContext） */\n        @DatabusProp(label = "创建人 ID", required = true, order = 3)\n        private String uid;\n\n        /**\n         * 流程标题（必填）。支持 {@code {{ $.xxx }}} 表达式，组件解析后传入 BPM 端。\n         */\n        @DatabusProp(\n            label = "流程标题", required = true, exprRole = ExprRole.DATA, order = 4,\n            description = "支持 {{ $.路径 }} 表达式拼接"\n        )\n        private String title;\n    }\n}\n', '初始迁移：内置 jar 件脚本化首版（seed 生成）', sysdate()),
    (1762000000001100009, 1762000000001000009, 1, 'java', 'package org.dromara.databus.script;\n\nimport lombok.extern.slf4j.Slf4j;\nimport org.dromara.common.core.exception.ServiceException;\nimport org.dromara.common.core.utils.SpringUtils;\nimport org.dromara.databus.component.DatabusNodeComponent;\nimport org.dromara.databus.component.schema.annotation.DatabusCmp;\nimport org.dromara.databus.connector.Connection;\nimport org.dromara.databus.connector.bpm.BpmHttpConnector;\nimport org.dromara.databus.connector.bpm.dto.BoCreateRequest;\nimport org.dromara.databus.connector.bpm.dto.BoItem;\nimport java.util.ArrayList;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\nimport lombok.Data;\nimport org.dromara.databus.component.schema.annotation.DatabusProp;\nimport org.dromara.databus.component.schema.enums.ExprRole;\nimport org.dromara.databus.component.schema.enums.WidgetKind;\n\n\n\n\n/**\n * BO_CREATE 组件（注册名 {@code boCreate}）。\n * <p>\n * 调 BPM 端 BO_CREATE 端点创建 BO 数据。响应 {@code {boResults: [{boName, records, createdCount}]}}\n * 整体存入 {@code $.<tag>.boResults}，并按 cfg.boList[i].rewrite.strategy 执行 6 种回写策略\n * （no/all/boId/add/exclude/include），策略语义与老系统 BoCreateProcessor 一致。\n *\n * <p>BPM 端不做回写（决策 9.1.2），回写在 Component 层完成；BPM 端不做字段重映射\n * （决策 9.1.3），Component 层在 boCreate 之前接 fieldMap 把数据形状准备好。\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = "boCreate", name = "BPM 建 BO", shortName = "建 BO",\n    icon = "ph:database", color = "#9c27b0",\n    description = "创建 BPM 业务对象（BO），method=create 时 bindId 必填且引用上一步 processStart.processInstanceId，支持 6 种回写策略", sort = 120,\n    dataExample = """\n        {"connectionId":"bpm-default","method":"create","bindId":"{{ $.processStart1.processInstanceId }}","uid":"admin","boList":[{"boName":"UserBO","sourcePath":"{{ $.request.users }}","rewrite":{"strategy":"all","path":"$.response.users"}}]}\n        """\n)\npublic class BoCreateComponent extends DatabusNodeComponent {\n\n    private static final String DEFAULT_METHOD = "create";\n\n    @Override\n    public void process() {\n        BoCreateCfg cfg = this.getCmpData(BoCreateCfg.class);\n        if (cfg == null) {\n            throw new ServiceException("BO_CREATE 组件缺少参数配置（tag=" + this.getTag() + "）");\n        }\n        String tag = this.getTag();\n        if (tag == null || tag.isBlank()) {\n            throw new ServiceException("BO_CREATE 组件缺少数据空间标识（tag）");\n        }\n        if (cfg.getConnectionId() == null || cfg.getConnectionId().isBlank()) {\n            throw new ServiceException("BO_CREATE 组件缺少 connectionId 配置（tag=" + tag + "）");\n        }\n        if (cfg.getUid() == null || cfg.getUid().isBlank()) {\n            throw new ServiceException("BO_CREATE 组件缺少 uid 配置（tag=" + tag + "）");\n        }\n        if (cfg.getBoList() == null || cfg.getBoList().isEmpty()) {\n            throw new ServiceException("BO_CREATE 组件缺少 boList 配置（tag=" + tag + "）");\n        }\n\n        // 参数解析：字符串经 resolve 求值（{{ $.路径 }} 或字面量）\n        String connectionId = resolveStr(cfg.getConnectionId());\n        String method = cfg.getMethod() == null || cfg.getMethod().isBlank()\n                ? DEFAULT_METHOD : resolveStr(cfg.getMethod());\n        if (!"create".equals(method) && !"createDataBO".equals(method)) {\n            throw new ServiceException("BO_CREATE 组件 method 仅支持 create / createDataBO，实际: " + method);\n        }\n        String bindId = resolveStr(cfg.getBindId());\n        if ("create".equals(method) && (bindId == null || bindId.isBlank())) {\n            throw new ServiceException("BO_CREATE 组件 method=create 时 bindId 必填（tag=" + tag + "）");\n        }\n        String uid = resolveStr(cfg.getUid());\n\n        // 组装 boList：从 sourcePath 读 List<Map> 作为 records\n        List<BoItem> boItems = new ArrayList<>(cfg.getBoList().size());\n        for (int i = 0; i < cfg.getBoList().size(); i++) {\n            BoCreateCfg.BoItemCfg itemCfg = cfg.getBoList().get(i);\n            if (itemCfg == null || itemCfg.getBoName() == null || itemCfg.getBoName().isBlank()) {\n                throw new ServiceException("BO_CREATE 组件 boList[" + i + "] 缺少 boName（tag=" + tag + "）");\n            }\n            if (itemCfg.getSourcePath() == null || itemCfg.getSourcePath().isBlank()) {\n                throw new ServiceException("BO_CREATE 组件 boList[" + i + "] 缺少 sourcePath（tag=" + tag + "）");\n            }\n            List<Map<String, Object>> records =\n                toRecordList(resolveParam(itemCfg.getSourcePath()), itemCfg.getSourcePath());\n            if (records == null || records.isEmpty()) {\n                throw new ServiceException("BO_CREATE 组件 boList[" + i + "] sourcePath 读到的 records 为空: "\n                        + itemCfg.getSourcePath());\n            }\n            BoItem item = new BoItem();\n            item.setBoName(itemCfg.getBoName());\n            item.setRecords(records);\n            boItems.add(item);\n        }\n\n        BpmHttpConnector connector = SpringUtils.getBean(BpmHttpConnector.class);\n        Connection conn = getDatabusContext().getConnection(connectionId);\n\n        BoCreateRequest request = new BoCreateRequest();\n        request.setMethod(method);\n        request.setBindId(bindId);\n        request.setUid(uid);\n        request.setBoList(boItems);\n\n        Object result = connector.boCreate(conn, request);\n        if (!(result instanceof Map<?, ?> resultMap)) {\n            throw new ServiceException("BO_CREATE 响应非 JSON 对象: " + result);\n        }\n        Object boResultsRaw = resultMap.get("boResults");\n        if (!(boResultsRaw instanceof List<?>)) {\n            throw new ServiceException("BO_CREATE 响应 boResults 非 List: " + boResultsRaw);\n        }\n        List<Map<String, Object>> boResults = convertResults(boResultsRaw);\n\n        // 整体 boResults 存一份到 $.<tag>.boResults，便于后续组件读 ID\n        save("$." + tag + ".boResults", boResults);\n\n        // 按顺序对应 cfg.boList 回写\n        if (boResults.size() != cfg.getBoList().size()) {\n            throw new ServiceException("BO_CREATE 响应 boResults 数量(" + boResults.size()\n                    + ")与配置 boList 数量(" + cfg.getBoList().size() + ")不一致");\n        }\n        int rewriteCount = 0;\n        for (int i = 0; i < cfg.getBoList().size(); i++) {\n            BoCreateCfg.BoItemCfg itemCfg = cfg.getBoList().get(i);\n            BoCreateCfg.RewriteCfg rewrite = itemCfg.getRewrite();\n            if (rewrite != null) {\n                rewriteCount += applyRewrite(rewrite, boResults.get(i), tag, i);\n            }\n        }\n\n        long createdCount = boResults.stream()\n            .mapToLong(r -> r.get("records") instanceof List<?> records ? records.size() : 0)\n            .sum();\n        List<String> sampleIds = new ArrayList<>();\n        for (Map<String, Object> boResult : boResults) {\n            if (boResult.get("records") instanceof List<?> records) {\n                for (Object item : records) {\n                    if (item instanceof Map<?, ?> record && record.get("ID") != null && sampleIds.size() < 2) {\n                        sampleIds.add(String.valueOf(record.get("ID")));\n                    }\n                }\n            }\n        }\n        StringBuilder summary = new StringBuilder("新建 BO ").append(createdCount).append(" 个");\n        if (!sampleIds.isEmpty()) {\n            summary.append("：").append(String.join("、", sampleIds));\n        }\n        if (rewriteCount > 0) {\n            summary.append("，回写来源 ").append(rewriteCount).append(" 条");\n        }\n        resultSummary(summary.toString());\n\n        log.info("[databus] boCreate 完成 tag={} 共 {} 项 BO", tag, boResults.size());\n    }\n\n    /**\n     * 执行单条 BO 的回写策略（6 策略，与老系统 BoCreateProcessor 一致）。\n     *\n     * @return 实际回写的记录条数（供步骤摘要统计），未回写返回 0\n     */\n    @SuppressWarnings("unchecked")\n    private int applyRewrite(BoCreateCfg.RewriteCfg rewrite, Map<String, Object> boResult,\n                             String tag, int index) {\n        String strategy = rewrite.getStrategy();\n        if (strategy == null || strategy.isBlank() || "no".equals(strategy)) {\n            return 0;\n        }\n        String path = rewrite.getPath();\n        if (path == null || path.isBlank()) {\n            log.warn("[databus] boCreate tag={} 第 {} 项策略 {} 缺少 path，跳过回写", tag, index, strategy);\n            return 0;\n        }\n        Object recordsRaw = boResult.get("records");\n        if (!(recordsRaw instanceof List<?> rawList)) {\n            log.warn("[databus] boCreate tag={} 第 {} 项 records 非 List，跳过回写", tag, index);\n            return 0;\n        }\n        List<Map<String, Object>> records = new ArrayList<>(rawList.size());\n        for (Object item : rawList) {\n            if (item instanceof Map<?, ?> map) {\n                records.add((Map<String, Object>) map);\n            } else {\n                log.warn("[databus] boCreate tag={} 第 {} 项 record 非 Map，跳过该条", tag, index);\n            }\n        }\n\n        switch (strategy) {\n            case "all" -> {\n                save(path, records);\n                return records.size();\n            }\n            case "boId" -> {\n                writeFieldsPerRecord(path, records, List.of("ID"), tag, index);\n                return records.size();\n            }\n            case "add" -> {\n                writeFieldsPerRecord(path, records, rewrite.getAddFields(), tag, index);\n                return records.size();\n            }\n            case "exclude" -> {\n                save(path, filterRecords(records, rewrite.getExcludes(), false));\n                return records.size();\n            }\n            case "include" -> {\n                if (rewrite.getIncludes() == null || rewrite.getIncludes().isEmpty()) {\n                    save(path, records);\n                } else {\n                    save(path, filterRecords(records, rewrite.getIncludes(), true));\n                }\n                return records.size();\n            }\n            default -> {\n                log.warn("[databus] boCreate tag={} 第 {} 项未知策略 {}，跳过", tag, index, strategy);\n                return 0;\n            }\n        }\n    }\n\n    /**\n     * add / boId：遍历 records[j]，对 fields 每字段写 {@code $.<path>[j].<field>}。\n     * <p>用基类 save（自动建父路径 + 数组扩容），路径拼 {@code <path>[j].<field>}。\n     */\n    private void writeFieldsPerRecord(String path, List<Map<String, Object>> records,\n                                      List<String> fields, String tag, int index) {\n        if (fields == null || fields.isEmpty()) {\n            log.warn("[databus] boCreate tag={} 第 {} 项 add/boId 策略缺少 addFields", tag, index);\n            return;\n        }\n        for (int j = 0; j < records.size(); j++) {\n            Map<String, Object> record = records.get(j);\n            for (String field : fields) {\n                save(path + "[" + j + "]." + field, record.get(field));\n            }\n        }\n    }\n\n    /**\n     * exclude（保留非 excludes 字段）/ include（只保留 includes 字段）公共过滤。\n     *\n     * @param fields   过滤字段列表\n     * @param keepFlag true=include（只保留），false=exclude（剔除）\n     */\n    private List<Map<String, Object>> filterRecords(List<Map<String, Object>> records,\n                                                    List<String> fields, boolean keepFlag) {\n        if (fields == null || fields.isEmpty()) {\n            return records;\n        }\n        List<Map<String, Object>> result = new ArrayList<>(records.size());\n        for (Map<String, Object> record : records) {\n            Map<String, Object> filtered = new LinkedHashMap<>(record.size());\n            record.forEach((key, value) -> {\n                boolean inFields = fields.contains(key);\n                boolean keep = keepFlag ? inFields : !inFields;\n                if (keep) {\n                    filtered.put(key, value);\n                }\n            });\n            result.add(filtered);\n        }\n        return result;\n    }\n\n    /**\n     * 把响应 boResults（List of LinkedHashMap）规整为 {@code List<Map<String, Object>>}。\n     */\n    @SuppressWarnings("unchecked")\n    private List<Map<String, Object>> convertResults(Object boResultsRaw) {\n        return (List<Map<String, Object>>) boResultsRaw;\n    }\n\n    /**\n     * 字符串参数解析：resolve 求值后统一转 String。\n     */\n    private String resolveStr(Object input) {\n        if (input == null) {\n            return null;\n        }\n        Object resolved = resolveParam(input);\n        return resolved == null ? null : resolved.toString();\n    }\n\n    /**\n     * BO_CREATE 组件（boCreate）的节点参数。\n     * <pre>\n     * {\n     *   "connectionId": "bpm-default",\n     *   "method": "create",            // 可选，默认 create；create / createDataBO\n     *   "bindId": "bo-001",            // method=create 时必填\n     *   "uid": "admin",                // 必填\n     *   "boList": [\n     *     {\n     *       "boName": "UserBO",         // 必填\n     *       "sourcePath": "{{ $.request.users }}",  // 必填，要数据表达式，求值 List<Map> 作为 records\n     *       "rewrite": {                // 可选，缺省策略 no\n     *         "strategy": "all",        // no / all / boId / add / exclude / include\n     *         "path": "$.response.users",  // 回写目标路径\n     *         "addFields": ["ID"],        // add / boId 用\n     *         "excludes": ["password"],   // exclude 用\n     *         "includes": ["ID", "name"]  // include 用（为空退化为 all）\n     *       }\n     *     }\n     *   ]\n     * }\n     * </pre>\n     *\n     * <p>6 回写策略语义（与老系统 BoCreateProcessor 一致，详见\n     * <a href="../../../../../../../../../../../docs/wiki/databus-bpm-connector-service-design.md">\n     * databus-bpm-connector-service-design §10.4</a>）：\n     * <ul>\n     *   <li><b>no</b>：不回写</li>\n     *   <li><b>all</b>：把 boResults[i].records 整体覆写到 {@code $.<rewrite.path>}</li>\n     *   <li><b>boId</b>：转化为 add + addFields=["ID"]，对每条记录的 ID 字段写 {@code $.<path>[j].ID}</li>\n     *   <li><b>add</b>：遍历 records 每条，对 addFields 中每个字段写 {@code $.<path>[j].<field>}</li>\n     *   <li><b>exclude</b>：从 records 过滤掉 excludes 字段后整体覆写</li>\n     *   <li><b>include</b>：从 records 只保留 includes 字段后整体覆写（includes 为空时退化为 all）</li>\n     * </ul>\n     *\n     * @author databus\n     */\n    @Data\n    public static class BoCreateCfg {\n\n        /** 连接实例 ID（必填） */\n        @DatabusProp(label = "连接", required = true, widget = WidgetKind.CONNECTION_SELECT, order = 1)\n        private String connectionId;\n\n        /** 创建方法：create（流程驱动，需 bindId）/ createDataBO（纯数据）。可选，默认 create */\n        @DatabusProp(\n            label = "创建方法", widget = WidgetKind.SELECT, order = 2,\n            options = {\n                @DatabusProp.Option(label = "流程驱动 create（需 bindId）", value = "create"),\n                @DatabusProp.Option(label = "纯数据 createDataBO", value = "createDataBO")\n            }\n        )\n        private String method;\n\n        /** bindId，method=create 时必填（通常引用上一步 processStart 的 processInstanceId） */\n        @DatabusProp(\n            label = "流程实例 bindId", order = 3,\n            placeholder = "{{ $.processStart1.processInstanceId }}",\n            description = "method=create 时必填：流程实例 ID",\n            showWhen = @DatabusProp.ShowWhen(field = "method", eq = "create")\n        )\n        private String bindId;\n\n        /** 用户 ID（必填，构造 UserContext） */\n        @DatabusProp(label = "用户 ID", required = true, order = 4)\n        private String uid;\n\n        /** BO 列表（必填），与 BPM 端响应 boResults 顺序一一对应 */\n        @DatabusProp(label = "BO 建表列表", required = true, order = 5)\n        private List<BoItemCfg> boList;\n\n        /**\n         * 单个 BO 项：BO 名称 + 数据空间源路径 + 回写策略。\n         */\n        @Data\n        public static class BoItemCfg {\n\n            /** BO 名称（必填） */\n            @DatabusProp(label = "BO 名称", required = true, order = 1)\n            private String boName;\n\n            /** 数据空间源表达式（必填，要数据，{@code {{ $.路径 }}}），求值 {@code List<Map<String, Object>>} 作为 records */\n            @DatabusProp(\n                label = "数据空间源表达式", required = true, exprRole = ExprRole.DATA, order = 2,\n                placeholder = "{{ $.数据空间.records }}"\n            )\n            private String sourcePath;\n\n            /** 回写策略配置（可选，缺省 strategy=no 不回写） */\n            @DatabusProp(label = "回写策略", order = 3)\n            private RewriteCfg rewrite;\n        }\n\n        /**\n         * 回写策略配置：strategy + 目标路径 + 策略相关字段。\n         */\n        @Data\n        public static class RewriteCfg {\n\n            /** 策略名：no / all / boId / add / exclude / include。必填 */\n            @DatabusProp(\n                label = "回写策略", required = true, widget = WidgetKind.SELECT, order = 1,\n                options = {\n                    @DatabusProp.Option(label = "不回写 no", value = "no"),\n                    @DatabusProp.Option(label = "整体覆写 all", value = "all"),\n                    @DatabusProp.Option(label = "回写 ID boId", value = "boId"),\n                    @DatabusProp.Option(label = "按字段回写 add", value = "add"),\n                    @DatabusProp.Option(label = "排除字段 exclude", value = "exclude"),\n                    @DatabusProp.Option(label = "只保留字段 include", value = "include")\n                }\n            )\n            private String strategy;\n\n            /** 回写目标路径，如 {@code $.response.users}（strategy=no 时可省略） */\n            @DatabusProp(\n                label = "回写目标路径", exprRole = ExprRole.TARGET, order = 2,\n                placeholder = "$.数据空间.目标",\n                showWhen = @DatabusProp.ShowWhen(field = "strategy", ne = "no")\n            )\n            private String path;\n\n            /** add / boId 策略用的字段列表 */\n            @DatabusProp(\n                label = "回写字段 addFields", order = 3,\n                description = "add：逐记录回写这些字段；boId 固定等价于 addFields=[ID]",\n                showWhen = @DatabusProp.ShowWhen(field = "strategy", in = {"add", "boId"})\n            )\n            private List<String> addFields;\n\n            /** exclude 策略用的过滤字段列表 */\n            @DatabusProp(\n                label = "排除字段 excludes", order = 4,\n                showWhen = @DatabusProp.ShowWhen(field = "strategy", eq = "exclude")\n            )\n            private List<String> excludes;\n\n            /** include 策略用的保留字段列表（为空时退化为 all） */\n            @DatabusProp(\n                label = "保留字段 includes", order = 5,\n                description = "为空时退化为 all",\n                showWhen = @DatabusProp.ShowWhen(field = "strategy", eq = "include")\n            )\n            private List<String> includes;\n        }\n    }\n}\n', '初始迁移：内置 jar 件脚本化首版（seed 生成）', sysdate()),
    (1762000000001100010, 1762000000001000010, 1, 'java', 'package org.dromara.databus.script;\n\nimport lombok.extern.slf4j.Slf4j;\nimport org.dromara.common.core.exception.ServiceException;\nimport org.dromara.common.core.utils.SpringUtils;\nimport org.dromara.databus.component.DatabusNodeComponent;\nimport org.dromara.databus.component.schema.annotation.DatabusCmp;\nimport org.dromara.databus.connector.Connection;\nimport org.dromara.databus.connector.bpm.BpmHttpConnector;\nimport org.dromara.databus.connector.bpm.dto.BoQueryRequest;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Map;\nimport lombok.Data;\nimport org.dromara.databus.component.schema.annotation.DatabusProp;\nimport org.dromara.databus.component.schema.enums.ExprRole;\nimport org.dromara.databus.component.schema.enums.WidgetKind;\n\n\n\n\n/**\n * BO_QUERY 组件（注册名 {@code boQuery}）。\n * <p>\n * 调 BPM 端 BO_QUERY 端点查询 BO 数据。支持 list / listPage / count 三种查询方法、\n * maxRecord 影响量前置校验、动态查询条件（conditionSourcePath 从数据空间读取）、\n * 关联表（mainField=relField）与子表（BINDID=主表 BINDID）数据挂载。\n *\n * <p>响应存 {@code $.<tag>.boName / $.<tag>.method / $.<tag>.records}（list/listPage）\n * 或 {@code $.<tag>.count}（count）；records 内嵌关联表/子表数据（键为对应 BO 名称）。\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = "boQuery", name = "BPM 查 BO", shortName = "查 BO",\n    icon = "ph:magnifying-glass", color = "#409eff",\n    description = "查询 BPM 业务对象（BO）数据，支持 list/listPage/count 三种方法、maxRecord 影响量校验、动态条件与关联表/子表挂载", sort = 130,\n    dataExample = """\n        {"connectionId":"bpm-default","main":{"boName":"BO_EU_API_TEST_MAIN","method":"list","maxRecord":50,"conditionSourcePath":"{{ $.request.conditions }}"},"sub":["BO_EU_API_TEST_SUB"]}\n        """\n)\npublic class BoQueryComponent extends DatabusNodeComponent {\n\n    private static final String DEFAULT_METHOD = "list";\n    private static final String METHOD_LIST = "list";\n    private static final String METHOD_LIST_PAGE = "listPage";\n    private static final String METHOD_COUNT = "count";\n\n    @Override\n    public void process() {\n        BoQueryCfg cfg = this.getCmpData(BoQueryCfg.class);\n        if (cfg == null) {\n            throw new ServiceException("BO_QUERY 组件缺少参数配置（tag=" + this.getTag() + "）");\n        }\n        String tag = this.getTag();\n        if (tag == null || tag.isBlank()) {\n            throw new ServiceException("BO_QUERY 组件缺少数据空间标识（tag）");\n        }\n        if (cfg.getConnectionId() == null || cfg.getConnectionId().isBlank()) {\n            throw new ServiceException("BO_QUERY 组件缺少 connectionId 配置（tag=" + tag + "）");\n        }\n        if (cfg.getMain() == null) {\n            throw new ServiceException("BO_QUERY 组件缺少 main 配置（tag=" + tag + "）");\n        }\n        BoQueryCfg.MainCfg mainCfg = cfg.getMain();\n        if (mainCfg.getBoName() == null || mainCfg.getBoName().isBlank()) {\n            throw new ServiceException("BO_QUERY 组件缺少 main.boName 配置（tag=" + tag + "）");\n        }\n        String method = mainCfg.getMethod() == null || mainCfg.getMethod().isBlank()\n                ? DEFAULT_METHOD : resolveStr(mainCfg.getMethod());\n        if (!METHOD_LIST.equals(method) && !METHOD_LIST_PAGE.equals(method) && !METHOD_COUNT.equals(method)) {\n            throw new ServiceException("BO_QUERY 组件 main.method 仅支持 list / listPage / count，实际: " + method);\n        }\n        if (METHOD_LIST_PAGE.equals(method)\n                && (mainCfg.getFirstRow() == null || mainCfg.getRowCount() == null)) {\n            throw new ServiceException("BO_QUERY 组件 method=listPage 时 main.firstRow / main.rowCount 必填（tag=" + tag + "）");\n        }\n\n        // 组装请求\n        BoQueryRequest request = new BoQueryRequest();\n        BoQueryRequest.MainQuery main = new BoQueryRequest.MainQuery();\n        main.setBoName(resolveStr(mainCfg.getBoName()));\n        main.setMethod(method);\n        main.setMaxRecord(mainCfg.getMaxRecord());\n        main.setFirstRow(mainCfg.getFirstRow());\n        main.setRowCount(mainCfg.getRowCount());\n        main.setConditions(readConditions(mainCfg.getConditionSourcePath()));\n        request.setMain(main);\n        if (cfg.getRelate() != null && !cfg.getRelate().isEmpty()) {\n            List<BoQueryRequest.RelateQuery> relateList = new ArrayList<>(cfg.getRelate().size());\n            for (int i = 0; i < cfg.getRelate().size(); i++) {\n                BoQueryCfg.RelateCfg relateCfg = cfg.getRelate().get(i);\n                if (relateCfg == null || relateCfg.getBoName() == null || relateCfg.getBoName().isBlank()\n                        || relateCfg.getMainField() == null || relateCfg.getMainField().isBlank()\n                        || relateCfg.getRelField() == null || relateCfg.getRelField().isBlank()) {\n                    throw new ServiceException("BO_QUERY 组件 relate[" + i + "] 缺少 boName / mainField / relField（tag=" + tag + "）");\n                }\n                BoQueryRequest.RelateQuery relate = new BoQueryRequest.RelateQuery();\n                relate.setBoName(relateCfg.getBoName());\n                relate.setMainField(relateCfg.getMainField());\n                relate.setRelField(relateCfg.getRelField());\n                relateList.add(relate);\n            }\n            request.setRelate(relateList);\n        }\n        request.setSub(cfg.getSub());\n\n        BpmHttpConnector connector = SpringUtils.getBean(BpmHttpConnector.class);\n        Connection conn = getDatabusContext().getConnection(resolveStr(cfg.getConnectionId()));\n\n        Object result = connector.boQuery(conn, request);\n        if (!(result instanceof Map<?, ?> resultMap)) {\n            throw new ServiceException("BO_QUERY 响应非 JSON 对象: " + result);\n        }\n\n        // 响应存数据空间：boName / method 固定，list/listPage 存 records，count 存 count\n        save("$." + tag + ".boName", resultMap.get("boName"));\n        save("$." + tag + ".method", resultMap.get("method"));\n        if (METHOD_COUNT.equals(method)) {\n            Object count = resultMap.get("count");\n            if (count == null) {\n                throw new ServiceException("BO_QUERY 响应缺少 count 字段: " + result);\n            }\n            save("$." + tag + ".count", count);\n            resultSummary("查询 " + main.getBoName() + "：共 " + count + " 条");\n        } else {\n            Object records = resultMap.get("records");\n            if (!(records instanceof List<?> recordList)) {\n                throw new ServiceException("BO_QUERY 响应 records 非 List: " + records);\n            }\n            save("$." + tag + ".records", records);\n            resultSummary("查询 " + main.getBoName() + "：命中 " + recordList.size() + " 条");\n        }\n        log.info("[databus] boQuery 完成 tag={} boName={} method={}", tag, main.getBoName(), method);\n    }\n\n    /**\n     * 从数据空间读取条件列表并映射为 QueryCondition（List&lt;Map&gt; → 强类型）。\n     * conditionSourcePath 为「要数据」字段（{@code {{ $.路径 }}}）；\n     * 表达式路径不存在时 resolve 抛错。\n     */\n    private List<BoQueryRequest.QueryCondition> readConditions(String conditionSourcePath) {\n        if (conditionSourcePath == null || conditionSourcePath.isBlank()) {\n            return null;\n        }\n        List<Map<String, Object>> rawList =\n            toRecordList(resolveParam(conditionSourcePath), conditionSourcePath);\n        List<BoQueryRequest.QueryCondition> conditions = new ArrayList<>(rawList.size());\n        for (int i = 0; i < rawList.size(); i++) {\n            Map<String, Object> raw = rawList.get(i);\n            if (raw == null || raw.get("fieldName") == null || raw.get("operator") == null) {\n                throw new ServiceException("BO_QUERY 组件条件[" + i + "] 缺少 fieldName / operator: " + raw);\n            }\n            BoQueryRequest.QueryCondition condition = new BoQueryRequest.QueryCondition();\n            condition.setFieldName(String.valueOf(raw.get("fieldName")));\n            condition.setOperator(String.valueOf(raw.get("operator")));\n            condition.setParamValue(raw.get("paramValue"));\n            Object valid = raw.get("valid");\n            condition.setValid(valid == null ? null : Boolean.parseBoolean(valid.toString()));\n            conditions.add(condition);\n        }\n        return conditions;\n    }\n\n    /**\n     * 字符串参数解析：resolve 求值后统一转 String。\n     */\n    private String resolveStr(Object input) {\n        if (input == null) {\n            return null;\n        }\n        Object resolved = resolveParam(input);\n        return resolved == null ? null : resolved.toString();\n    }\n\n    /**\n     * BO_QUERY 组件（boQuery）的节点参数。\n     * <pre>\n     * {\n     *   "connectionId": "bpm-default",   // 必填\n     *   "main": {\n     *     "boName": "BO_EU_API_TEST_MAIN",  // 必填，主表 BO 名称\n     *     "method": "list",                 // 可选，默认 list；list / listPage / count\n     *     "maxRecord": 100,                 // 可选，大于 0 时先 count 校验，超出报错\n     *     "firstRow": 0,                    // method=listPage 必填\n     *     "rowCount": 20,                   // method=listPage 必填\n     *     "conditionSourcePath": "{{ $.request.conditions }}"  // 可选，要数据表达式，求值条件列表\n     *   },\n     *   "relate": [                        // 可选，关联表配置\n     *     { "boName": "RelBO", "mainField": "CODE", "relField": "REL_CODE" }\n     *   ],\n     *   "sub": ["SubBO"]                   // 可选，子表 BO 名称列表（按 BINDID=主表 BINDID 关联）\n     * }\n     * </pre>\n     *\n     * <p>条件列表从 conditionSourcePath 读取（List&lt;Map&gt;，键为 fieldName/operator/paramValue/valid），\n     * 支持从上游数据动态构造；paramValue 原值透传（类型转换用 fieldMap 预处理）。\n     *\n     * <p>响应存 {@code $.<tag>.boName / $.<tag>.method / $.<tag>.records}（list/listPage）\n     * 或 {@code $.<tag>.count}（count）；records 内嵌关联表/子表数据（键为对应 BO 名称）。\n     *\n     * @author databus\n     */\n    @Data\n    public static class BoQueryCfg {\n\n        /** 连接实例 ID（必填） */\n        @DatabusProp(label = "连接", required = true, widget = WidgetKind.CONNECTION_SELECT, order = 1)\n        private String connectionId;\n\n        /** 主表查询配置（必填） */\n        @DatabusProp(label = "主表查询", required = true, order = 2)\n        private MainCfg main;\n\n        /** 关联表配置列表（可选） */\n        @DatabusProp(label = "关联表配置", order = 3)\n        private List<RelateCfg> relate;\n\n        /** 子表 BO 名称列表（可选） */\n        @DatabusProp(label = "子表 BO 名称", order = 4, description = "按 BINDID=主表 BINDID 挂载，输入后回车添加")\n        private List<String> sub;\n\n        /**\n         * 主表查询配置。\n         */\n        @Data\n        public static class MainCfg {\n\n            /** 主表 BO 名称（必填） */\n            @DatabusProp(label = "主表 BO 名称", required = true, order = 1)\n            private String boName;\n\n            /** 查询方法：list / listPage / count。可选，默认 list */\n            @DatabusProp(\n                label = "查询方法", widget = WidgetKind.SELECT, order = 2,\n                options = {\n                    @DatabusProp.Option(label = "列表 list", value = "list"),\n                    @DatabusProp.Option(label = "分页 listPage", value = "listPage"),\n                    @DatabusProp.Option(label = "计数 count", value = "count")\n                }\n            )\n            private String method;\n\n            /** 最大影响数据量（可选），大于 0 时先 count 校验，超出报错 */\n            @DatabusProp(label = "最大数据量校验", order = 3, description = ">0 时先 count 校验，超出报错")\n            private Long maxRecord;\n\n            /** 分页起始行（method=listPage 必填） */\n            @DatabusProp(label = "分页起始行 firstRow", order = 4, showWhen = @DatabusProp.ShowWhen(field = "method", eq = "listPage"))\n            private Integer firstRow;\n\n            /** 分页行数（method=listPage 必填） */\n            @DatabusProp(label = "分页行数 rowCount", order = 5, showWhen = @DatabusProp.ShowWhen(field = "method", eq = "listPage"))\n            private Integer rowCount;\n\n            /** 条件列表源表达式（可选，要数据，{@code {{ $.路径 }}}），求值 {@code List<Map>}，键为 fieldName/operator/paramValue/valid */\n            @DatabusProp(\n                label = "动态条件列表路径", exprRole = ExprRole.DATA, order = 6,\n                description = "求值条件列表 List<Map>（键 fieldName/operator/paramValue/valid），可由上游动态构造"\n            )\n            private String conditionSourcePath;\n        }\n\n        /**\n         * 关联表配置。\n         */\n        @Data\n        public static class RelateCfg {\n\n            /** 关联表 BO 名称（必填） */\n            @DatabusProp(label = "关联表 BO 名称", required = true, order = 1)\n            private String boName;\n\n            /** 主表关联字段（必填） */\n            @DatabusProp(label = "主表关联字段", required = true, order = 2)\n            private String mainField;\n\n            /** 关联表匹配字段（必填） */\n            @DatabusProp(label = "关联表匹配字段", required = true, order = 3)\n            private String relField;\n        }\n    }\n}\n', '初始迁移：内置 jar 件脚本化首版（seed 生成）', sysdate()),
    (1762000000001100011, 1762000000001000011, 1, 'java', 'package org.dromara.databus.script;\n\nimport lombok.extern.slf4j.Slf4j;\nimport org.dromara.common.core.exception.ServiceException;\nimport org.dromara.common.core.utils.SpringUtils;\nimport org.dromara.databus.component.DatabusNodeComponent;\nimport org.dromara.databus.component.schema.annotation.DatabusCmp;\nimport org.dromara.databus.connector.Connection;\nimport org.dromara.databus.connector.bpm.BpmHttpConnector;\nimport org.dromara.databus.connector.bpm.dto.BoItem;\nimport org.dromara.databus.connector.bpm.dto.BoUpdateRequest;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Map;\nimport lombok.Data;\nimport org.dromara.databus.component.schema.annotation.DatabusProp;\nimport org.dromara.databus.component.schema.enums.ExprRole;\nimport org.dromara.databus.component.schema.enums.WidgetKind;\n\n\n\n\n/**\n * BO_UPDATE 组件（注册名 {@code boUpdate}）。\n * <p>\n * 调 BPM 端 BO_UPDATE 端点按记录 ID 更新 BO 数据。records 每条必须含 ID 字段\n * （可先经 boQuery 查出记录再整体回写）；BPM 端整体事务 all-or-nothing，\n * 任一条失败全部回滚并抛错。\n *\n * <p>响应 {@code {boResults: [{boName, updatedCount}]}} 存入 {@code $.<tag>.boResults}。\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = "boUpdate", name = "BPM 改 BO", shortName = "改 BO",\n    icon = "ph:pencil-line", color = "#e6a23c",\n    description = "按记录 ID 更新 BPM 业务对象（BO）数据，records 必须含 ID 字段（可先 boQuery 查出再整体回写），BPM 端整体事务 all-or-nothing", sort = 140,\n    dataExample = """\n        {"connectionId":"bpm-default","boList":[{"boName":"BO_EU_API_TEST_MAIN","sourcePath":"{{ $.boQuery1.records }}"}]}\n        """\n)\npublic class BoUpdateComponent extends DatabusNodeComponent {\n\n    private static final String FIELD_ID = "ID";\n\n    @Override\n    public void process() {\n        BoUpdateCfg cfg = this.getCmpData(BoUpdateCfg.class);\n        if (cfg == null) {\n            throw new ServiceException("BO_UPDATE 组件缺少参数配置（tag=" + this.getTag() + "）");\n        }\n        String tag = this.getTag();\n        if (tag == null || tag.isBlank()) {\n            throw new ServiceException("BO_UPDATE 组件缺少数据空间标识（tag）");\n        }\n        if (cfg.getConnectionId() == null || cfg.getConnectionId().isBlank()) {\n            throw new ServiceException("BO_UPDATE 组件缺少 connectionId 配置（tag=" + tag + "）");\n        }\n        if (cfg.getBoList() == null || cfg.getBoList().isEmpty()) {\n            throw new ServiceException("BO_UPDATE 组件缺少 boList 配置（tag=" + tag + "）");\n        }\n\n        // 组装 boList：从 sourcePath 读 List<Map> 作为 records，逐条校验 ID\n        List<BoItem> boItems = new ArrayList<>(cfg.getBoList().size());\n        for (int i = 0; i < cfg.getBoList().size(); i++) {\n            BoUpdateCfg.BoItemCfg itemCfg = cfg.getBoList().get(i);\n            if (itemCfg == null || itemCfg.getBoName() == null || itemCfg.getBoName().isBlank()) {\n                throw new ServiceException("BO_UPDATE 组件 boList[" + i + "] 缺少 boName（tag=" + tag + "）");\n            }\n            if (itemCfg.getSourcePath() == null || itemCfg.getSourcePath().isBlank()) {\n                throw new ServiceException("BO_UPDATE 组件 boList[" + i + "] 缺少 sourcePath（tag=" + tag + "）");\n            }\n            List<Map<String, Object>> records =\n                toRecordList(resolveParam(itemCfg.getSourcePath()), itemCfg.getSourcePath());\n            if (records == null || records.isEmpty()) {\n                throw new ServiceException("BO_UPDATE 组件 boList[" + i + "] sourcePath 读到的 records 为空: "\n                        + itemCfg.getSourcePath());\n            }\n            for (int j = 0; j < records.size(); j++) {\n                Map<String, Object> record = records.get(j);\n                if (record == null || record.get(FIELD_ID) == null) {\n                    throw new ServiceException("BO_UPDATE 组件 boList[" + i + "].records[" + j\n                            + "] 缺少 ID 字段（按记录 ID 定位更新）");\n                }\n            }\n            BoItem item = new BoItem();\n            item.setBoName(itemCfg.getBoName());\n            item.setRecords(records);\n            boItems.add(item);\n        }\n\n        BpmHttpConnector connector = SpringUtils.getBean(BpmHttpConnector.class);\n        Connection conn = getDatabusContext().getConnection(resolveStr(cfg.getConnectionId()));\n\n        BoUpdateRequest request = new BoUpdateRequest();\n        request.setBoList(boItems);\n\n        Object result = connector.boUpdate(conn, request);\n        if (!(result instanceof Map<?, ?> resultMap)) {\n            throw new ServiceException("BO_UPDATE 响应非 JSON 对象: " + result);\n        }\n        Object boResultsRaw = resultMap.get("boResults");\n        if (!(boResultsRaw instanceof List<?>)) {\n            throw new ServiceException("BO_UPDATE 响应 boResults 非 List: " + boResultsRaw);\n        }\n\n        // boResults 存到 $.<tag>.boResults（[{boName, updatedCount}]）\n        save("$." + tag + ".boResults", boResultsRaw);\n        long updatedTotal = 0;\n        String firstBoName = null;\n        for (Object item : (List<?>) boResultsRaw) {\n            if (item instanceof Map<?, ?> boResult) {\n                if (firstBoName == null && boResult.get("boName") != null) {\n                    firstBoName = String.valueOf(boResult.get("boName"));\n                }\n                if (boResult.get("updatedCount") instanceof Number number) {\n                    updatedTotal += number.longValue();\n                }\n            }\n        }\n        String summaryText = "更新 BO " + updatedTotal + " 条";\n        if (firstBoName != null) {\n            summaryText += "（" + firstBoName + "）";\n        }\n        resultSummary(summaryText);\n        log.info("[databus] boUpdate 完成 tag={} 共 {} 项 BO", tag, ((List<?>) boResultsRaw).size());\n    }\n\n    /**\n     * 字符串参数解析：resolve 求值后统一转 String。\n     */\n    private String resolveStr(Object input) {\n        if (input == null) {\n            return null;\n        }\n        Object resolved = resolveParam(input);\n        return resolved == null ? null : resolved.toString();\n    }\n\n    /**\n     * BO_UPDATE 组件（boUpdate）的节点参数。\n     * <pre>\n     * {\n     *   "connectionId": "bpm-default",   // 必填\n     *   "boList": [\n     *     {\n     *       "boName": "UserBO",           // 必填\n     *       "sourcePath": "{{ $.request.users }}"  // 必填，要数据表达式，求值 List&lt;Map&gt; 作为 records，\n     *                                        // 每条 records 必须含 ID 字段（按记录 ID 定位更新）\n     *     }\n     *   ]\n     * }\n     * </pre>\n     *\n     * <p>BPM 端整体事务 all-or-nothing：任一条更新失败全部回滚。\n     * 响应存 {@code $.<tag>.boResults} = [{boName, updatedCount}]。\n     *\n     * @author databus\n     */\n    @Data\n    public static class BoUpdateCfg {\n\n        /** 连接实例 ID（必填） */\n        @DatabusProp(label = "连接", required = true, widget = WidgetKind.CONNECTION_SELECT, order = 1)\n        private String connectionId;\n\n        /** BO 列表（必填） */\n        @DatabusProp(label = "BO 更新列表", required = true, order = 2)\n        private List<BoItemCfg> boList;\n\n        /**\n         * 单个 BO 项：BO 名称 + 数据空间源路径。\n         */\n        @Data\n        public static class BoItemCfg {\n\n            /** BO 名称（必填） */\n            @DatabusProp(label = "BO 名称", required = true, order = 1)\n            private String boName;\n\n            /** 数据空间源表达式（必填，要数据，{@code {{ $.路径 }}}），求值 {@code List<Map<String, Object>>} 作为 records，每条必须含 ID */\n            @DatabusProp(\n                label = "数据空间源表达式", required = true, exprRole = ExprRole.DATA, order = 2,\n                placeholder = "{{ $.数据空间.records }}",\n                description = "求值 List<Map> 作为 records，每条记录必须含 ID 字段"\n            )\n            private String sourcePath;\n        }\n    }\n}\n', '初始迁移：内置 jar 件脚本化首版（seed 生成）', sysdate()),
    (1762000000001100012, 1762000000001000012, 1, 'java', 'package org.dromara.databus.script;\n\nimport lombok.extern.slf4j.Slf4j;\nimport org.dromara.common.core.exception.ServiceException;\nimport org.dromara.common.core.utils.SpringUtils;\nimport org.dromara.databus.component.DatabusNodeComponent;\nimport org.dromara.databus.component.schema.annotation.DatabusCmp;\nimport org.dromara.databus.connector.Connection;\nimport org.dromara.databus.connector.bpm.BpmHttpConnector;\nimport org.dromara.databus.connector.bpm.dto.BoDeleteRequest;\nimport org.dromara.databus.connector.bpm.dto.BoItem;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Map;\nimport lombok.Data;\nimport org.dromara.databus.component.schema.annotation.DatabusProp;\nimport org.dromara.databus.component.schema.enums.ExprRole;\nimport org.dromara.databus.component.schema.enums.WidgetKind;\n\n\n\n\n/**\n * BO_DELETE 组件（注册名 {@code boDelete}）。\n * <p>\n * 调 BPM 端 BO_DELETE 端点删除 BO 数据。两种模式：\n * method=remove（默认）按记录 ID 逐条删除；method=removeByBindId 按流程实例 ID\n * 批量删除该流程下所有 BO 数据。BPM 端整体事务 all-or-nothing。\n *\n * <p>响应 {@code {boResults: [{boName, removedCount}]}} 存入 {@code $.<tag>.boResults}。\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = "boDelete", name = "BPM 删 BO", shortName = "删 BO",\n    icon = "ph:trash", color = "#f56c6c",\n    description = "删除 BPM 业务对象（BO）数据，method=remove 按记录 ID 逐条删 / removeByBindId 按流程实例批量删，BPM 端整体事务 all-or-nothing", sort = 150,\n    dataExample = """\n        {"connectionId":"bpm-default","method":"remove","boList":[{"boName":"BO_EU_API_TEST_MAIN","sourcePath":"{{ $.boQuery1.records }}"}]}\n        """\n)\npublic class BoDeleteComponent extends DatabusNodeComponent {\n\n    private static final String DEFAULT_METHOD = "remove";\n    private static final String METHOD_REMOVE = "remove";\n    private static final String METHOD_REMOVE_BY_BIND_ID = "removeByBindId";\n\n    private static final String FIELD_ID = "ID";\n    private static final String FIELD_BIND_ID = "BINDID";\n\n    @Override\n    public void process() {\n        BoDeleteCfg cfg = this.getCmpData(BoDeleteCfg.class);\n        if (cfg == null) {\n            throw new ServiceException("BO_DELETE 组件缺少参数配置（tag=" + this.getTag() + "）");\n        }\n        String tag = this.getTag();\n        if (tag == null || tag.isBlank()) {\n            throw new ServiceException("BO_DELETE 组件缺少数据空间标识（tag）");\n        }\n        if (cfg.getConnectionId() == null || cfg.getConnectionId().isBlank()) {\n            throw new ServiceException("BO_DELETE 组件缺少 connectionId 配置（tag=" + tag + "）");\n        }\n        String method = cfg.getMethod() == null || cfg.getMethod().isBlank()\n                ? DEFAULT_METHOD : resolveStr(cfg.getMethod());\n        if (!METHOD_REMOVE.equals(method) && !METHOD_REMOVE_BY_BIND_ID.equals(method)) {\n            throw new ServiceException("BO_DELETE 组件 method 仅支持 remove / removeByBindId，实际: " + method);\n        }\n        if (cfg.getBoList() == null || cfg.getBoList().isEmpty()) {\n            throw new ServiceException("BO_DELETE 组件缺少 boList 配置（tag=" + tag + "）");\n        }\n\n        // 组装 boList：从 sourcePath 读 List<Map> 作为 records，按 method 校验必需字段\n        String requiredField = METHOD_REMOVE_BY_BIND_ID.equals(method) ? FIELD_BIND_ID : FIELD_ID;\n        List<BoItem> boItems = new ArrayList<>(cfg.getBoList().size());\n        for (int i = 0; i < cfg.getBoList().size(); i++) {\n            BoDeleteCfg.BoItemCfg itemCfg = cfg.getBoList().get(i);\n            if (itemCfg == null || itemCfg.getBoName() == null || itemCfg.getBoName().isBlank()) {\n                throw new ServiceException("BO_DELETE 组件 boList[" + i + "] 缺少 boName（tag=" + tag + "）");\n            }\n            if (itemCfg.getSourcePath() == null || itemCfg.getSourcePath().isBlank()) {\n                throw new ServiceException("BO_DELETE 组件 boList[" + i + "] 缺少 sourcePath（tag=" + tag + "）");\n            }\n            List<Map<String, Object>> records =\n                toRecordList(resolveParam(itemCfg.getSourcePath()), itemCfg.getSourcePath());\n            if (records == null || records.isEmpty()) {\n                throw new ServiceException("BO_DELETE 组件 boList[" + i + "] sourcePath 读到的 records 为空: "\n                        + itemCfg.getSourcePath());\n            }\n            for (int j = 0; j < records.size(); j++) {\n                Map<String, Object> record = records.get(j);\n                if (record == null || record.get(requiredField) == null) {\n                    throw new ServiceException("BO_DELETE 组件 boList[" + i + "].records[" + j\n                            + "] 缺少 " + requiredField + " 字段（method=" + method + "）");\n                }\n            }\n            BoItem item = new BoItem();\n            item.setBoName(itemCfg.getBoName());\n            item.setRecords(records);\n            boItems.add(item);\n        }\n\n        BpmHttpConnector connector = SpringUtils.getBean(BpmHttpConnector.class);\n        Connection conn = getDatabusContext().getConnection(resolveStr(cfg.getConnectionId()));\n\n        BoDeleteRequest request = new BoDeleteRequest();\n        request.setMethod(method);\n        request.setBoList(boItems);\n\n        Object result = connector.boDelete(conn, request);\n        if (!(result instanceof Map<?, ?> resultMap)) {\n            throw new ServiceException("BO_DELETE 响应非 JSON 对象: " + result);\n        }\n        Object boResultsRaw = resultMap.get("boResults");\n        if (!(boResultsRaw instanceof List<?>)) {\n            throw new ServiceException("BO_DELETE 响应 boResults 非 List: " + boResultsRaw);\n        }\n\n        // boResults 存到 $.<tag>.boResults（[{boName, removedCount}]）\n        save("$." + tag + ".boResults", boResultsRaw);\n        long removedTotal = 0;\n        String firstBoName = null;\n        for (Object item : (List<?>) boResultsRaw) {\n            if (item instanceof Map<?, ?> boResult) {\n                if (firstBoName == null && boResult.get("boName") != null) {\n                    firstBoName = String.valueOf(boResult.get("boName"));\n                }\n                if (boResult.get("removedCount") instanceof Number number) {\n                    removedTotal += number.longValue();\n                }\n            }\n        }\n        String summaryText = "删除 BO " + removedTotal + " 条";\n        if (firstBoName != null) {\n            summaryText += "（" + firstBoName + "）";\n        }\n        resultSummary(summaryText);\n        log.info("[databus] boDelete 完成 tag={} method={} 共 {} 项 BO", tag, method, ((List<?>) boResultsRaw).size());\n    }\n\n    /**\n     * 字符串参数解析：resolve 求值后统一转 String。\n     */\n    private String resolveStr(Object input) {\n        if (input == null) {\n            return null;\n        }\n        Object resolved = resolveParam(input);\n        return resolved == null ? null : resolved.toString();\n    }\n\n    /**\n     * BO_DELETE 组件（boDelete）的节点参数。\n     * <pre>\n     * {\n     *   "connectionId": "bpm-default",   // 必填\n     *   "method": "remove",              // 可选，默认 remove；remove / removeByBindId\n     *   "boList": [\n     *     {\n     *       "boName": "UserBO",           // 必填\n     *       "sourcePath": "{{ $.boQuery1.records }}"  // 必填，要数据表达式，求值 List&lt;Map&gt; 作为 records；\n     *                                           // method=remove 每条必须含 ID，\n     *                                           // method=removeByBindId 每条必须含 BINDID\n     *     }\n     *   ]\n     * }\n     * </pre>\n     *\n     * <p>BPM 端整体事务 all-or-nothing：任一删除失败全部回滚。\n     * 响应存 {@code $.<tag>.boResults} = [{boName, removedCount}]。\n     *\n     * @author databus\n     */\n    @Data\n    public static class BoDeleteCfg {\n\n        /** 连接实例 ID（必填） */\n        @DatabusProp(label = "连接", required = true, widget = WidgetKind.CONNECTION_SELECT, order = 1)\n        private String connectionId;\n\n        /** 删除方式：remove（按记录 ID）/ removeByBindId（按流程实例 ID）。可选，默认 remove */\n        @DatabusProp(\n            label = "删除方式", widget = WidgetKind.SELECT, order = 2,\n            options = {\n                @DatabusProp.Option(label = "按记录 ID 删除 remove", value = "remove"),\n                @DatabusProp.Option(label = "按流程实例删除 removeByBindId", value = "removeByBindId")\n            }\n        )\n        private String method;\n\n        /** BO 列表（必填） */\n        @DatabusProp(label = "BO 删除列表", required = true, order = 3)\n        private List<BoItemCfg> boList;\n\n        /**\n         * 单个 BO 项：BO 名称 + 数据空间源路径。\n         */\n        @Data\n        public static class BoItemCfg {\n\n            /** BO 名称（必填） */\n            @DatabusProp(label = "BO 名称", required = true, order = 1)\n            private String boName;\n\n            /** 数据空间源表达式（必填，要数据，{@code {{ $.路径 }}}），求值 {@code List<Map<String, Object>>} 作为 records */\n            @DatabusProp(\n                label = "数据空间源表达式", required = true, exprRole = ExprRole.DATA, order = 2,\n                description = "remove 每条记录必须含 ID；removeByBindId 每条必须含 BINDID"\n            )\n            private String sourcePath;\n        }\n    }\n}\n', '初始迁移：内置 jar 件脚本化首版（seed 生成）', sysdate()),
    (1762000000001100013, 1762000000001000013, 1, 'java', 'package org.dromara.databus.script;\n\nimport lombok.extern.slf4j.Slf4j;\nimport org.dromara.common.core.exception.ServiceException;\nimport org.dromara.common.core.utils.SpringUtils;\nimport org.dromara.databus.component.DatabusNodeComponent;\nimport org.dromara.databus.component.schema.annotation.DatabusCmp;\nimport org.dromara.databus.connector.Connection;\nimport org.dromara.databus.connector.bpm.BpmHttpConnector;\nimport org.dromara.databus.connector.bpm.dto.ProcessTerminateRequest;\nimport java.util.Map;\nimport lombok.Data;\nimport org.dromara.databus.component.schema.annotation.DatabusProp;\nimport org.dromara.databus.component.schema.enums.ExprRole;\nimport org.dromara.databus.component.schema.enums.WidgetKind;\n\n\n\n\n/**\n * PROCESS_TERMINATE 组件（注册名 {@code processTerminate}）。\n * <p>\n * 调 BPM 端 PROCESS_TERMINATE 端点终止流程实例。BPM 端先查流程实例校验存在性\n * （不存在抛错，规避老系统静默返回）；已结束时不重复终止，返回 terminated=false\n * + alreadyEnded=true（幂等语义，不报错）。\n *\n * <p>响应 {@code {processInstanceId, terminated, alreadyEnded}} 存入 {@code $.<tag>.result}。\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = "processTerminate", name = "BPM 终止流程", shortName = "终止流程",\n    icon = "ph:prohibit", color = "#909399",\n    description = "终止 BPM 流程实例（userId 为终止操作人），流程已结束时幂等返回 terminated=false 不报错", sort = 160,\n    dataExample = """\n        {"connectionId":"bpm-default","instanceId":"{{ $.processStart1.processInstanceId }}","userId":"admin"}\n        """\n)\npublic class ProcessTerminateComponent extends DatabusNodeComponent {\n\n    @Override\n    public void process() {\n        ProcessTerminateCfg cfg = this.getCmpData(ProcessTerminateCfg.class);\n        if (cfg == null) {\n            throw new ServiceException("PROCESS_TERMINATE 组件缺少参数配置（tag=" + this.getTag() + "）");\n        }\n        String tag = this.getTag();\n        if (tag == null || tag.isBlank()) {\n            throw new ServiceException("PROCESS_TERMINATE 组件缺少数据空间标识（tag）");\n        }\n        if (cfg.getConnectionId() == null || cfg.getConnectionId().isBlank()) {\n            throw new ServiceException("PROCESS_TERMINATE 组件缺少 connectionId 配置（tag=" + tag + "）");\n        }\n        String instanceId = resolveStr(cfg.getInstanceId());\n        if (instanceId == null || instanceId.isBlank()) {\n            throw new ServiceException("PROCESS_TERMINATE 组件缺少 instanceId 配置（tag=" + tag + "）");\n        }\n        String userId = resolveStr(cfg.getUserId());\n        if (userId == null || userId.isBlank()) {\n            throw new ServiceException("PROCESS_TERMINATE 组件缺少 userId 配置（tag=" + tag + "）");\n        }\n\n        BpmHttpConnector connector = SpringUtils.getBean(BpmHttpConnector.class);\n        Connection conn = getDatabusContext().getConnection(resolveStr(cfg.getConnectionId()));\n\n        ProcessTerminateRequest request = new ProcessTerminateRequest();\n        request.setInstanceId(instanceId);\n        request.setUserId(userId);\n\n        Object result = connector.processTerminate(conn, request);\n        if (!(result instanceof Map<?, ?> resultMap)) {\n            throw new ServiceException("PROCESS_TERMINATE 响应非 JSON 对象: " + result);\n        }\n\n        // 响应存到 $.<tag>.result（{processInstanceId, terminated, alreadyEnded}）\n        save("$." + tag + ".result", resultMap);\n        if (Boolean.TRUE.equals(resultMap.get("terminated"))) {\n            resultSummary("终止流程：" + instanceId);\n        } else if (Boolean.TRUE.equals(resultMap.get("alreadyEnded"))) {\n            resultSummary("流程此前已结束：" + instanceId);\n        } else {\n            resultSummary("终止未生效：" + instanceId);\n        }\n        log.info("[databus] processTerminate 完成 tag={} instanceId={} terminated={}",\n                tag, instanceId, resultMap.get("terminated"));\n    }\n\n    /**\n     * 字符串参数解析：resolve 求值后统一转 String。\n     */\n    private String resolveStr(Object input) {\n        if (input == null) {\n            return null;\n        }\n        Object resolved = resolveParam(input);\n        return resolved == null ? null : resolved.toString();\n    }\n\n    /**\n     * PROCESS_TERMINATE 组件（processTerminate）的节点参数。\n     * <pre>\n     * {\n     *   "connectionId": "bpm-default",                          // 必填\n     *   "instanceId": "{{ $.processStart1.processInstanceId }}", // 必填，流程实例 ID（字面量或表达式）\n     *   "userId": "admin"                                       // 必填，终止操作人（字面量或表达式）\n     * }\n     * </pre>\n     *\n     * <p>响应存 {@code $.<tag>.result} = {processInstanceId, terminated, alreadyEnded}；\n     * 流程已结束时 terminated=false + alreadyEnded=true（幂等，不报错）。\n     *\n     * @author databus\n     */\n    @Data\n    public static class ProcessTerminateCfg {\n\n        /** 连接实例 ID（必填） */\n        @DatabusProp(label = "连接", required = true, widget = WidgetKind.CONNECTION_SELECT, order = 1)\n        private String connectionId;\n\n        /** 流程实例 ID（必填，字面量或 {@code {{ $.路径 }}} 表达式） */\n        @DatabusProp(\n            label = "流程实例 ID", required = true, exprRole = ExprRole.DATA, order = 2,\n            placeholder = "{{ $.processStart1.processInstanceId }}"\n        )\n        private String instanceId;\n\n        /** 终止操作人用户 ID（必填，字面量或 {@code {{ $.路径 }}} 表达式） */\n        @DatabusProp(label = "终止操作人", required = true, exprRole = ExprRole.DATA, order = 3)\n        private String userId;\n    }\n}\n', '初始迁移：内置 jar 件脚本化首版（seed 生成）', sysdate()),
    (1762000000001100014, 1762000000001000014, 1, 'java', 'package org.dromara.databus.script;\n\nimport lombok.extern.slf4j.Slf4j;\nimport org.dromara.common.core.exception.ServiceException;\nimport org.dromara.common.core.utils.SpringUtils;\nimport org.dromara.databus.component.DatabusNodeComponent;\nimport org.dromara.databus.component.schema.annotation.DatabusCmp;\nimport org.dromara.databus.connector.Connection;\nimport org.dromara.databus.connector.bpm.BpmHttpConnector;\nimport org.dromara.databus.connector.bpm.dto.TaskCompleteRequest;\nimport java.util.List;\nimport java.util.Map;\nimport lombok.Data;\nimport org.dromara.databus.component.schema.annotation.DatabusProp;\nimport org.dromara.databus.component.schema.enums.ExprRole;\nimport org.dromara.databus.component.schema.enums.WidgetKind;\n\n\n\n\n/**\n * TASK_COMPLETE 组件（注册名 {@code taskComplete}）。\n * <p>\n * 调 BPM 端 TASK_COMPLETE 端点提交流程实例的所有活跃任务。响应\n * {@code {processInstanceId, processEnded, completedTaskIds, failedTaskIds, failedErrors}}\n * 按字段平铺写入数据空间 {@code $.<tag>.*}。\n *\n * <p>BPM 端 code 始终 0（决策 9.1.1：部分失败语义由 Connector/Component 翻译）。本组件\n * 拿到响应后看 {@code failedTaskIds}：非空 + cfg.failOnError=true 抛 ServiceException 中断；\n * 非空 + cfg.failOnError=false 仅 log.warn 不抛，调用方可在后续节点读\n * {@code $.<tag>.failedTaskIds} 自行决策。\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = "taskComplete", name = "BPM 完任务", shortName = "完任务",\n    icon = "ph:seal-check", color = "#67c23a",\n    description = "按 processInstanceId 提交 BPM 任务（全部尝试），部分失败按 failOnError 决定是否中断", sort = 170,\n    dataExample = """\n        {"connectionId":"bpm-default","processInstanceId":"{{ $.processStart1.processInstanceId }}","uid":"admin","failOnError":false}\n        """\n)\npublic class TaskCompleteComponent extends DatabusNodeComponent {\n\n    @Override\n    public void process() {\n        TaskCompleteCfg cfg = this.getCmpData(TaskCompleteCfg.class);\n        if (cfg == null) {\n            throw new ServiceException("TASK_COMPLETE 组件缺少参数配置（tag=" + this.getTag() + "）");\n        }\n        String tag = this.getTag();\n        if (tag == null || tag.isBlank()) {\n            throw new ServiceException("TASK_COMPLETE 组件缺少数据空间标识（tag）");\n        }\n        if (cfg.getConnectionId() == null || cfg.getConnectionId().isBlank()) {\n            throw new ServiceException("TASK_COMPLETE 组件缺少 connectionId 配置（tag=" + tag + "）");\n        }\n        if (cfg.getProcessInstanceId() == null || cfg.getProcessInstanceId().isBlank()) {\n            throw new ServiceException("TASK_COMPLETE 组件缺少 processInstanceId 配置（tag=" + tag + "）");\n        }\n        if (cfg.getUid() == null || cfg.getUid().isBlank()) {\n            throw new ServiceException("TASK_COMPLETE 组件缺少 uid 配置（tag=" + tag + "）");\n        }\n\n        // 参数解析：connectionId/processInstanceId/uid 经 resolve 求值（{{ $.路径 }} 或字面量）\n        String connectionId = resolveStr(cfg.getConnectionId());\n        String processInstanceId = resolveStr(cfg.getProcessInstanceId());\n        String uid = resolveStr(cfg.getUid());\n        boolean failOnError = Boolean.TRUE.equals(cfg.getFailOnError());\n\n        BpmHttpConnector connector = SpringUtils.getBean(BpmHttpConnector.class);\n        Connection conn = getDatabusContext().getConnection(connectionId);\n\n        TaskCompleteRequest request = new TaskCompleteRequest();\n        request.setProcessInstanceId(processInstanceId);\n        request.setUid(uid);\n\n        Object result = connector.taskComplete(conn, request);\n        if (!(result instanceof Map<?, ?> resultMap)) {\n            throw new ServiceException("TASK_COMPLETE 响应非 JSON 对象: " + result);\n        }\n        // 平铺 processInstanceId / processEnded / completedTaskIds / failedTaskIds / failedErrors\n        resultMap.forEach((key, value) -> save("$." + tag + "." + key, value));\n\n        int completedCount = resultMap.get("completedTaskIds") instanceof List<?> completedList\n                ? completedList.size() : 0;\n        int failedCount = resultMap.get("failedTaskIds") instanceof List<?> failedIdList\n                ? failedIdList.size() : 0;\n        String taskSummary = "任务提交：成功 " + completedCount + " 个";\n        if (failedCount > 0) {\n            taskSummary += "，失败 " + failedCount + " 个";\n        }\n        if (Boolean.TRUE.equals(resultMap.get("processEnded"))) {\n            taskSummary += "，流程已结束";\n        }\n        resultSummary(taskSummary);\n\n        // 部分失败语义翻译（决策 9.1.3）\n        Object failedTaskIdsRaw = resultMap.get("failedTaskIds");\n        if (failedTaskIdsRaw instanceof List<?> failedList && !failedList.isEmpty()) {\n            String errMsg = "TASK_COMPLETE 部分任务失败 tag=" + tag\n                    + " failedTaskIds=" + failedList\n                    + " completedTaskIds=" + resultMap.get("completedTaskIds");\n            if (failOnError) {\n                throw new ServiceException(errMsg);\n            }\n            log.warn("[databus] {}", errMsg);\n        }\n        log.info("[databus] taskComplete 完成 tag={} processEnded={}",\n                tag, resultMap.get("processEnded"));\n    }\n\n    /**\n     * 字符串参数解析：resolve 求值（{{ $.路径 }} 表达式或字面量）后统一转 String。\n     */\n    private String resolveStr(Object input) {\n        if (input == null) {\n            return null;\n        }\n        Object resolved = resolveParam(input);\n        return resolved == null ? null : resolved.toString();\n    }\n\n    /**\n     * TASK_COMPLETE 组件（taskComplete）的节点参数。\n     * <pre>\n     * {\n     *   "connectionId": "bpm-default",\n     *   "processInstanceId": "{{ $.processStart1.processInstanceId }}",  // 必填\n     *   "uid": "admin",                                            // 必填\n     *   "failOnError": false                                       // 可选，默认 false\n     * }\n     * </pre>\n     * failOnError 控制 BPM 端返回部分失败（failedTaskIds 非空）时是否抛异常：\n     * <ul>\n     *   <li>true：抛 ServiceException 中断后续流程</li>\n     *   <li>false：仅 log.warn 不抛，调用方可在后续节点读 {@code $.<tag>.failedTaskIds} 自行决策</li>\n     * </ul>\n     * 决策 9.1.3：TASK_COMPLETE 全部尝试 + failedTaskIds 记录 + code 非 0 表示部分失败。\n     *\n     * @author databus\n     */\n    @Data\n    public static class TaskCompleteCfg {\n\n        /** 连接实例 ID（必填） */\n        @DatabusProp(label = "连接", required = true, widget = WidgetKind.CONNECTION_SELECT, order = 1)\n        private String connectionId;\n\n        /** 流程实例 ID（必填，字面量或 {@code {{ $.路径 }}} 表达式） */\n        @DatabusProp(\n            label = "流程实例 ID", required = true, exprRole = ExprRole.DATA, order = 2,\n            placeholder = "{{ $.processStart1.processInstanceId }}"\n        )\n        private String processInstanceId;\n\n        /** 提交人用户 ID（必填，构造 UserContext） */\n        @DatabusProp(label = "提交人 ID", required = true, order = 3)\n        private String uid;\n\n        /** 部分失败时是否抛异常（可选，默认 false：仅 warn 不抛） */\n        @DatabusProp(\n            label = "部分失败时中断流程", widget = WidgetKind.BOOLEAN, order = 4,\n            description = "开启：任一任务失败即抛异常中断；关闭（默认）：仅告警，失败任务 ID 写入 $.<tag>.failedTaskIds"\n        )\n        private Boolean failOnError;\n    }\n}\n', '初始迁移：内置 jar 件脚本化首版（seed 生成）', sysdate()),
    (1762000000001100015, 1762000000001000015, 1, 'java', 'package org.dromara.databus.script;\n\nimport lombok.extern.slf4j.Slf4j;\nimport org.dromara.common.core.exception.ServiceException;\nimport org.dromara.common.core.utils.SpringUtils;\nimport org.dromara.databus.component.DatabusNodeComponent;\nimport org.dromara.databus.component.schema.annotation.DatabusCmp;\nimport org.dromara.databus.connector.Connection;\nimport org.dromara.databus.connector.bpm.BpmHttpConnector;\nimport org.dromara.databus.connector.bpm.dto.RdsExecuteRequest;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Map;\nimport lombok.Data;\nimport org.dromara.databus.component.schema.annotation.DatabusProp;\nimport org.dromara.databus.component.schema.enums.WidgetKind;\n\n\n\n\n/**\n * RDS_EXECUTE 组件（注册名 {@code rdsExecute}）。\n * <p>\n * 通过 BPM connector 执行 BPM 后台注册的 RDS 数据源 SQL，对应老系统 RdsConfigProcessor\n * （SqlValueProcessor 的规则引擎 @sqlValue 标量取数并入本组件标量方法）。\n * 支持 getString/getInt/getLong/getDouble/getMap/getMaps/update/batch 八种方法，\n * batch 支持多 SQL 无参与单 SQL 批量参数两种模式。\n *\n * <p>args 参数逐元素走统一 resolveParam（字面量 / {@code {{ $.路径 }}} 表达式），SQL 文本原样透传。\n * 响应存 {@code $.<tag>.method} 与 {@code $.<tag>.data}。\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = "rdsExecute", name = "BPM SQL 执行", shortName = "SQL 执行",\n    icon = "ph:table", color = "#16a34a",\n    description = "在 BPM 后台注册的 RDS 数据源上执行 SQL：标量/单行/多行查询、更新与批量（8 种方法），结果存 $.数据空间.data", sort = 180,\n    dataExample = """\n        {"connectionId":"bpm-default","rdsId":"default","method":"getMaps","sql":"select userid,ext1 as idCard from orguser where ext1=?","args":["{{ $.request.idCard }}"],"maxRows":100}\n        """\n)\npublic class RdsExecuteComponent extends DatabusNodeComponent {\n\n    private static final String DEFAULT_METHOD = "getMaps";\n\n    @Override\n    public void process() {\n        RdsExecuteCfg cfg = this.getCmpData(RdsExecuteCfg.class);\n        if (cfg == null) {\n            throw new ServiceException("RDS_EXECUTE 组件缺少参数配置（tag=" + this.getTag() + "）");\n        }\n        String tag = this.getTag();\n        if (tag == null || tag.isBlank()) {\n            throw new ServiceException("RDS_EXECUTE 组件缺少数据空间标识（tag）");\n        }\n        if (cfg.getConnectionId() == null || cfg.getConnectionId().isBlank()) {\n            throw new ServiceException("RDS_EXECUTE 组件缺少 connectionId 配置（tag=" + tag + "）");\n        }\n        String rdsId = resolveStr(cfg.getRdsId());\n        if (rdsId == null || rdsId.isBlank()) {\n            throw new ServiceException("RDS_EXECUTE 组件缺少 rdsId 配置（tag=" + tag + "）");\n        }\n        if (cfg.getSql() == null) {\n            throw new ServiceException("RDS_EXECUTE 组件缺少 sql 配置（tag=" + tag + "）");\n        }\n        String method = cfg.getMethod() == null || cfg.getMethod().isBlank()\n                ? DEFAULT_METHOD : resolveStr(cfg.getMethod());\n\n        // 组装请求：SQL 原样透传；args 逐元素参数解析（batch 嵌套数组递归解析）\n        RdsExecuteRequest request = new RdsExecuteRequest();\n        request.setRdsId(rdsId);\n        request.setMethod(method);\n        request.setSql(cfg.getSql());\n        request.setArgs(resolveArgs(cfg.getArgs()));\n        request.setFetchSize(cfg.getFetchSize());\n        request.setMaxRows(cfg.getMaxRows());\n\n        BpmHttpConnector connector = SpringUtils.getBean(BpmHttpConnector.class);\n        Connection conn = getDatabusContext().getConnection(resolveStr(cfg.getConnectionId()));\n\n        Object result = connector.rdsExecute(conn, request);\n        if (!(result instanceof Map<?, ?> resultMap)) {\n            throw new ServiceException("RDS_EXECUTE 响应非 JSON 对象: " + result);\n        }\n        Object methodEcho = resultMap.get("method");\n        if (methodEcho == null) {\n            throw new ServiceException("RDS_EXECUTE 响应缺少 method 字段: " + result);\n        }\n        save("$." + tag + ".method", methodEcho);\n        Object data = resultMap.get("data");\n        save("$." + tag + ".data", data);\n        resultSummary(buildRdsSummary(String.valueOf(methodEcho), data));\n        log.info("[databus] rdsExecute 完成 tag={} rdsId={} method={}", tag, rdsId, methodEcho);\n    }\n\n    /**\n     * 按 method 生成步骤人话摘要：查询类报行数、更新类报影响行数、标量报取值、批量报累计影响。\n     */\n    private String buildRdsSummary(String method, Object data) {\n        return switch (method) {\n            case "getMaps" -> data instanceof List<?> list\n                    ? "查询返回 " + list.size() + " 行" : "查询返回非列表结果";\n            case "getMap" -> data == null ? "查询未命中行" : "查询命中 1 行";\n            case "update" -> "更新影响 " + data + " 行";\n            case "batch" -> {\n                long sum = 0;\n                if (data instanceof List<?> list) {\n                    for (Object item : list) {\n                        if (item instanceof Number number) {\n                            sum += number.longValue();\n                        }\n                    }\n                    yield "批量执行 " + list.size() + " 条，影响 " + sum + " 行";\n                }\n                yield "批量返回非列表结果";\n            }\n            case "getString", "getInt", "getLong", "getDouble" -> "取值（" + method + "）：" + data;\n            default -> "SQL 执行：" + method;\n        };\n    }\n\n    /**\n     * args 递归解析：List 逐元素递归（batch 批量参数是数组的数组），\n     * 叶子走 resolveParam（字面量 / {@code {{ $.路径 }}}；数字布尔原样返回）。\n     */\n    private Object resolveArgs(Object args) {\n        if (args == null) {\n            return null;\n        }\n        if (args instanceof List<?> list) {\n            List<Object> resolved = new ArrayList<>(list.size());\n            for (Object item : list) {\n                resolved.add(resolveArgs(item));\n            }\n            return resolved;\n        }\n        return resolveParam(args);\n    }\n\n    /**\n     * 字符串参数解析：resolve 求值后统一转 String。\n     */\n    private String resolveStr(Object input) {\n        if (input == null) {\n            return null;\n        }\n        Object resolved = resolveParam(input);\n        return resolved == null ? null : resolved.toString();\n    }\n\n    /**\n     * RDS_EXECUTE 组件（rdsExecute）的节点参数。\n     * <pre>\n     * {\n     *   "connectionId": "bpm-default",   // 必填，BPM 连接实例\n     *   "rdsId": "default",              // 必填，BPM 后台注册的 RDS 数据源 ID\n     *   "method": "getMaps",             // 必填：getString/getInt/getLong/getDouble/getMap/getMaps/update/batch\n     *   "sql": "select * from t where id=?",  // 字符串；batch 多 SQL 时为字符串数组\n     *   "args": ["{{ $.request.id }}"],  // 可选，参数元素为字面量或 {{ $.路径 }} 表达式；batch 批量参数时为数组的数组\n     *   "fetchSize": 100,                // 可选，>0 生效\n     *   "maxRows": 1000                  // 可选，>0 生效\n     * }\n     * </pre>\n     *\n     * <p>响应存 {@code $.<tag>.method} 与 {@code $.<tag>.data}：\n     * 标量方法 data 为标量；getMap/getMaps 为 Map/List；update 为影响行数；batch 为每次执行行数数组。\n     *\n     * @author databus\n     */\n    @Data\n    public static class RdsExecuteCfg {\n\n        /** 连接实例 ID（必填） */\n        @DatabusProp(label = "连接", required = true, widget = WidgetKind.CONNECTION_SELECT, order = 1)\n        private String connectionId;\n\n        /** BPM 后台注册的 RDS 数据源 ID（必填） */\n        @DatabusProp(label = "RDS 数据源 ID", required = true, order = 2)\n        private String rdsId;\n\n        /** 执行方法：getString/getInt/getLong/getDouble/getMap/getMaps/update/batch（必填） */\n        @DatabusProp(\n            label = "执行方法", required = true, widget = WidgetKind.SELECT, order = 3,\n            options = {\n                @DatabusProp.Option(label = "查字符串 getString", value = "getString"),\n                @DatabusProp.Option(label = "查整数 getInt", value = "getInt"),\n                @DatabusProp.Option(label = "查长整数 getLong", value = "getLong"),\n                @DatabusProp.Option(label = "查浮点数 getDouble", value = "getDouble"),\n                @DatabusProp.Option(label = "查单行 getMap", value = "getMap"),\n                @DatabusProp.Option(label = "查多行 getMaps", value = "getMaps"),\n                @DatabusProp.Option(label = "更新 update", value = "update"),\n                @DatabusProp.Option(label = "批量执行 batch", value = "batch")\n            }\n        )\n        private String method;\n\n        /** SQL：字符串；batch 多 SQL 模式为字符串数组（必填，SQL 文本原样透传不走路径解析） */\n        @DatabusProp(\n            label = "SQL 语句", required = true, order = 4,\n            description = "SQL 原样透传，参数用 ? 占位写到「SQL 参数」；batch 模式用 JSON 高级模式填字符串数组"\n        )\n        private Object sql;\n\n        /** 参数：数组/单值；batch 批量参数模式为数组的数组。元素走 resolveParam 解析 */\n        @DatabusProp(\n            label = "SQL 参数", order = 5,\n            description = "JSON 数组，元素为字面量或 {{ $.路径 }} 表达式（与 ? 占位顺序一致）；batch 模式为数组的数组"\n        )\n        private Object args;\n\n        /** 抓取大小（可选，>0 生效） */\n        @DatabusProp(label = "抓取大小", order = 6)\n        private Integer fetchSize;\n\n        /** 最大行数（可选，>0 生效） */\n        @DatabusProp(label = "最大行数", order = 7)\n        private Integer maxRows;\n    }\n}\n', '初始迁移：内置 jar 件脚本化首版（seed 生成）', sysdate()),
    (1762000000001100016, 1762000000001000016, 1, 'java', 'package org.dromara.databus.script;\n\nimport lombok.extern.slf4j.Slf4j;\nimport org.dromara.common.core.exception.ServiceException;\nimport org.dromara.common.core.utils.SpringUtils;\nimport org.dromara.databus.component.DatabusNodeComponent;\nimport org.dromara.databus.component.schema.annotation.DatabusCmp;\nimport org.dromara.databus.connector.Connection;\nimport org.dromara.databus.connector.bpm.BpmHttpConnector;\nimport org.dromara.databus.connector.bpm.dto.IdCardToUserIdRequest;\nimport org.dromara.databus.context.PathResolver;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.regex.Pattern;\nimport lombok.Data;\nimport org.dromara.databus.component.schema.annotation.DatabusProp;\nimport org.dromara.databus.component.schema.enums.ExprRole;\nimport org.dromara.databus.component.schema.enums.WidgetKind;\n\n\n\n\n/**\n * IDCARD_TO_USERID 组件（注册名 {@code idCardToUserId}）。\n * <p>\n * 对应老系统 IdCardToUserIdProcessor：字段级组件，按配置的多个 path 逐个读取以\n * separator 分隔的身份证号字符串（输入拆分与输出拼接使用同一分隔符，默认逗号），\n * 调 BPM 端查 ORGUSER.EXT1 换 userId，结果原样写回同一路径。\n *\n * <p>失败语义（比老系统的静默 log 收紧）：某字段全部身份证号未匹配到用户时抛错，\n * 防止把空值写回业务字段；部分未匹配时告警并写回命中部分（与老系统 join 命中项行为一致）。\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = "idCardToUserId", name = "身份证换用户", shortName = "证换用户",\n    icon = "ph:identification-card", color = "#0891b2",\n    description = "按 path 表达式（{{ $.路径 }}）读取逗号分隔的身份证号，查 BPM 用户表换成 userId 写回解包路径；全部未命中报错，部分未命中告警", sort = 190,\n    dataExample = """\n        {"connectionId":"bpm-default","fields":[{"path":"{{ $.request.idCards }}","separator":","}]}\n        """\n)\npublic class IdCardToUserIdComponent extends DatabusNodeComponent {\n\n    private static final String DEFAULT_SEPARATOR = ",";\n\n    @Override\n    public void process() {\n        IdCardToUserIdCfg cfg = this.getCmpData(IdCardToUserIdCfg.class);\n        if (cfg == null) {\n            throw new ServiceException("IDCARD_TO_USERID 组件缺少参数配置（tag=" + this.getTag() + "）");\n        }\n        String tag = this.getTag();\n        if (tag == null || tag.isBlank()) {\n            throw new ServiceException("IDCARD_TO_USERID 组件缺少数据空间标识（tag）");\n        }\n        if (cfg.getConnectionId() == null || cfg.getConnectionId().isBlank()) {\n            throw new ServiceException("IDCARD_TO_USERID 组件缺少 connectionId 配置（tag=" + tag + "）");\n        }\n        if (cfg.getFields() == null || cfg.getFields().isEmpty()) {\n            throw new ServiceException("IDCARD_TO_USERID 组件缺少 fields 配置（tag=" + tag + "）");\n        }\n\n        BpmHttpConnector connector = SpringUtils.getBean(BpmHttpConnector.class);\n        Connection conn = getDatabusContext().getConnection(cfg.getConnectionId());\n\n        int converted = 0;\n        int totalIdCards = 0;\n        int totalMissed = 0;\n        for (int i = 0; i < cfg.getFields().size(); i++) {\n            IdCardToUserIdCfg.FieldCfg field = cfg.getFields().get(i);\n            if (field == null || field.getPath() == null || field.getPath().isBlank()) {\n                throw new ServiceException("IDCARD_TO_USERID 组件 fields[" + i + "].path 不能为空（tag=" + tag + "）");\n            }\n            String pathExpr = field.getPath();\n            // path 既「要数据」（取身份证串）又用于原地写回：整字段表达式读取，写回用解包裸路径\n            String resolvedPath = PathResolver.wholeExpression(pathExpr);\n            if (resolvedPath == null) {\n                throw new ServiceException("IDCARD_TO_USERID 组件 fields[" + i\n                    + "].path 必须为 {{ $.路径 }} 形式（tag=" + tag + "）：" + pathExpr);\n            }\n            Object rawValue = resolveParam(pathExpr);\n            String raw = rawValue == null ? null : rawValue.toString();\n            if (raw == null || raw.isBlank()) {\n                // 与老系统一致：值为空只告警跳过，不写回\n                log.warn("[databus] idCardToUserId 路径 {} 身份证号为空，跳过 tag={}", resolvedPath, tag);\n                continue;\n            }\n            String separator = field.getSeparator() == null || field.getSeparator().isBlank()\n                    ? DEFAULT_SEPARATOR : field.getSeparator();\n\n            IdCardToUserIdRequest request = new IdCardToUserIdRequest();\n            // 输入拆分与输出拼接必须用同一 separator（Pattern.quote 防 | ; 等正则元字符）；\n            // 空段不过滤，由 BPM 端归入 missed，保持段语义与拼接端一致\n            request.setIdCards(List.of(raw.split(Pattern.quote(separator))));\n            request.setSeparator(separator);\n\n            Object result = connector.idCardToUserId(conn, request);\n            if (!(result instanceof Map<?, ?> resultMap)) {\n                throw new ServiceException("IDCARD_TO_USERID 响应非 JSON 对象: " + result);\n            }\n            String userIds = resultMap.get("userIds") == null ? "" : String.valueOf(resultMap.get("userIds"));\n            if (userIds.isEmpty()) {\n                throw new ServiceException("IDCARD_TO_USERID 路径 " + resolvedPath\n                        + " 的全部身份证号均未匹配到 BPM 用户（tag=" + tag + "），原值: " + raw);\n            }\n            totalIdCards += request.getIdCards().size();\n            Object missed = resultMap.get("missed");\n            if (missed instanceof List<?> missedList && !missedList.isEmpty()) {\n                totalMissed += missedList.size();\n                log.warn("[databus] idCardToUserId 路径 {} 有 {} 个身份证号未匹配: {} tag={}",\n                        resolvedPath, missedList.size(), missedList, tag);\n            }\n            // 原地写回解包后的裸路径\n            save(resolvedPath, userIds);\n            converted++;\n        }\n        String idCardSummary = totalIdCards + " 个身份证：命中 " + (totalIdCards - totalMissed)\n                + "，未命中 " + totalMissed;\n        if (converted > 1) {\n            idCardSummary += "（" + converted + " 个字段）";\n        }\n        resultSummary(idCardSummary);\n        log.info("[databus] idCardToUserId 完成 tag={} 转换字段数={}", tag, converted);\n    }\n\n    /**\n     * IDCARD_TO_USERID 组件（idCardToUserId）的节点参数。\n     * <pre>\n     * {\n     *   "connectionId": "bpm-default",   // 必填，BPM 连接实例\n     *   "fields": [                      // 必填，字段列表（多字段原地写回）\n     *     { "path": "{{ $.request.idCards }}", "separator": "," }\n     *   ]\n     * }\n     * </pre>\n     *\n     * <p>每个 path 表达式（要数据，{@code {{ $.路径 }}}）指向一个以 separator 分隔的身份证号字符串；\n     * 组件按同一 separator 拆分输入，调 BPM 端批量换 userId 后，再把命中的 userId\n     * 按该 separator 连接写回解包后的同一路径。\n     * 全部未命中抛错；部分未命中告警并写回命中部分。\n     *\n     * @author databus\n     */\n    @Data\n    public static class IdCardToUserIdCfg {\n\n        /** 连接实例 ID（必填） */\n        @DatabusProp(label = "连接", required = true, widget = WidgetKind.CONNECTION_SELECT, order = 1)\n        private String connectionId;\n\n        /** 字段配置列表（必填） */\n        @DatabusProp(label = "换 ID 字段列表", required = true, order = 2)\n        private List<FieldCfg> fields;\n\n        /**\n         * 单个字段配置。\n         */\n        @Data\n        public static class FieldCfg {\n\n            /**\n             * 身份证号表达式（必填，要数据，{@code {{ $.路径 }}}），值为 separator 分隔字符串；\n             * 结果写回解包后的同一路径\n             */\n            @DatabusProp(\n                label = "身份证号表达式", required = true, exprRole = ExprRole.DATA, order = 1,\n                description = "求值为分隔符拼接的身份证号字符串，换得的 userId 原地写回同一路径"\n            )\n            private String path;\n\n            /** 输入拆分与输出拼接共用的分隔符，可选，默认 ","（支持 | ; 等特殊字符） */\n            @DatabusProp(label = "分隔符", order = 2, placeholder = ",")\n            private String separator;\n        }\n    }\n}\n', '初始迁移：内置 jar 件脚本化首版（seed 生成）', sysdate()),
    (1762000000001100017, 1762000000001000017, 1, 'java', 'package org.dromara.databus.script;\n\nimport cn.hutool.crypto.digest.DigestUtil;\nimport lombok.extern.slf4j.Slf4j;\nimport org.dromara.common.core.exception.ServiceException;\nimport org.dromara.common.core.utils.SpringUtils;\nimport org.dromara.databus.component.DatabusNodeComponent;\nimport org.dromara.databus.component.schema.annotation.DatabusCmp;\nimport org.dromara.databus.connector.Connection;\nimport org.dromara.databus.connector.bpm.BpmHttpConnector;\nimport org.dromara.databus.connector.bpm.dto.FileUploadRequest;\nimport java.util.ArrayList;\nimport java.util.Base64;\nimport java.util.List;\nimport java.util.Locale;\nimport java.util.Map;\nimport lombok.Data;\nimport org.dromara.databus.component.schema.annotation.DatabusProp;\nimport org.dromara.databus.component.schema.enums.ExprRole;\nimport org.dromara.databus.component.schema.enums.WidgetKind;\n\n\n\n\n/**\n * FILE_UPLOAD 组件（注册名 {@code fileUpload}）。\n *\n * <p>从数据空间读取文件数组（fileName + base64 fileContent），逐文件先在本地完成\n * 可选的摘要校验（md5/sha1/sha256/sha512），再通过 BPM connector 上传到目标 BO 记录附件字段。\n * 对应老系统 Base64ToFileProcessor（旧命名方向相反）；旧 processor 的全局单值校验\n * 改为逐文件携带 checkMethod/checksum。\n *\n * <p>响应存 {@code $.<tag>.uploadedCount} 与 {@code $.<tag>.files}。\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = "fileUpload", name = "BPM 上传附件", shortName = "上传附件",\n    icon = "ph:upload-simple", color = "#7c3aed",\n    description = "sourcePath 表达式（{{ $.路径 }}）取出文件数组（base64），本地摘要校验后上传到 BO 记录附件字段，结果存 $.数据空间.files", sort = 200,\n    dataExample = """\n        {"connectionId":"bpm-default","sourcePath":"{{ $.request.files }}","boId":"{{ $.boCreate1.boResults[0].records[0].ID }}","appId":"com.awspaas.user.apps.data.bus","boName":"BO_EU_API_TEST_MAIN","boItemName":"BO_FIELD_FILE","processInstId":"{{ $.processStart1.processInstanceId }}","validateChecksum":false}\n        """\n)\npublic class FileUploadComponent extends DatabusNodeComponent {\n\n    @Override\n    public void process() {\n        FileUploadCfg cfg = this.getCmpData(FileUploadCfg.class);\n        if (cfg == null) {\n            throw new ServiceException("FILE_UPLOAD 组件缺少参数配置（tag=" + this.getTag() + "）");\n        }\n        String tag = this.getTag();\n        if (tag == null || tag.isBlank()) {\n            throw new ServiceException("FILE_UPLOAD 组件缺少数据空间标识（tag）");\n        }\n        if (isBlank(cfg.getConnectionId()) || isBlank(cfg.getSourcePath())) {\n            throw new ServiceException("FILE_UPLOAD 组件缺少 connectionId / sourcePath 配置（tag=" + tag + "）");\n        }\n        String boId = resolveStr(cfg.getBoId());\n        String appId = resolveStr(cfg.getAppId());\n        String boName = resolveStr(cfg.getBoName());\n        String boItemName = resolveStr(cfg.getBoItemName());\n        if (isBlank(boId) || isBlank(appId) || isBlank(boName) || isBlank(boItemName)) {\n            throw new ServiceException("FILE_UPLOAD 组件缺少 boId / appId / boName / boItemName 配置（tag=" + tag + "）");\n        }\n\n        List<Map<String, Object>> sourceFiles =\n            toRecordList(resolveParam(cfg.getSourcePath()), cfg.getSourcePath());\n        if (sourceFiles == null || sourceFiles.isEmpty()) {\n            throw new ServiceException("FILE_UPLOAD 源文件列表为空：" + cfg.getSourcePath());\n        }\n\n        boolean requireChecksum = Boolean.TRUE.equals(cfg.getValidateChecksum());\n        List<FileUploadRequest.FileUploadItem> items = new ArrayList<>();\n        for (Map<String, Object> src : sourceFiles) {\n            String fileName = strOf(src.get("fileName"));\n            String fileContent = strOf(src.get("fileContent"));\n            if (isBlank(fileName) || isBlank(fileContent)) {\n                throw new ServiceException("FILE_UPLOAD 文件项缺少 fileName / fileContent（tag=" + tag + "）");\n            }\n\n            String checkMethod = strOf(src.get("checkMethod"));\n            String checksum = strOf(src.get("checksum"));\n            if (!isBlank(checkMethod) || !isBlank(checksum)) {\n                verifyChecksum(fileName, fileContent, checkMethod, checksum);\n            } else if (requireChecksum) {\n                throw new ServiceException("文件 " + fileName + " 缺少 checkMethod / checksum（validateChecksum=true）");\n            }\n\n            FileUploadRequest.FileUploadItem item = new FileUploadRequest.FileUploadItem();\n            item.setFileName(fileName);\n            item.setFileContent(fileContent);\n            Object securityLevel = src.get("securityLevel");\n            if (securityLevel instanceof Number number) {\n                item.setSecurityLevel(number.intValue());\n            }\n            items.add(item);\n        }\n\n        FileUploadRequest request = new FileUploadRequest();\n        request.setBoId(boId);\n        request.setAppId(appId);\n        request.setBoName(boName);\n        request.setBoItemName(boItemName);\n        request.setProcessInstId(blankToNull(resolveStr(cfg.getProcessInstId())));\n        request.setTaskInstId(blankToNull(resolveStr(cfg.getTaskInstId())));\n        request.setFiles(items);\n\n        BpmHttpConnector connector = SpringUtils.getBean(BpmHttpConnector.class);\n        Connection conn = getDatabusContext().getConnection(resolveStr(cfg.getConnectionId()));\n\n        Object result = connector.fileUpload(conn, request);\n        if (!(result instanceof Map<?, ?> resultMap)) {\n            throw new ServiceException("FILE_UPLOAD 响应非 JSON 对象: " + result);\n        }\n        save("$." + tag + ".uploadedCount", resultMap.get("uploadedCount"));\n        save("$." + tag + ".files", resultMap.get("files"));\n        resultSummary("上传 " + items.size() + " 个附件");\n        log.info("[databus] fileUpload 完成 tag={} count={}", tag, items.size());\n    }\n\n    /**\n     * 本地摘要校验：base64 解码后按 checkMethod 计算实际摘要，与期望 checksum 十六进制忽略大小写比较。\n     */\n    private void verifyChecksum(String fileName, String fileContent, String checkMethod, String expected) {\n        if (isBlank(checkMethod) || isBlank(expected)) {\n            throw new ServiceException("文件 " + fileName + " 校验配置不完整：checkMethod / checksum 需同时提供");\n        }\n        final byte[] bytes;\n        try {\n            bytes = Base64.getDecoder().decode(fileContent);\n        } catch (Exception e) {\n            throw new ServiceException("文件 " + fileName + " base64 解码失败: " + e.getMessage());\n        }\n        String actual = switch (checkMethod.toLowerCase(Locale.ROOT)) {\n            case "md5" -> DigestUtil.md5Hex(bytes);\n            case "sha1" -> DigestUtil.sha1Hex(bytes);\n            case "sha256" -> DigestUtil.sha256Hex(bytes);\n            case "sha512" -> DigestUtil.sha512Hex(bytes);\n            default -> throw new ServiceException("文件 " + fileName + " 不支持的摘要方法: " + checkMethod);\n        };\n        if (!actual.equalsIgnoreCase(expected)) {\n            throw new ServiceException(String.format(\n                    "文件 %s 摘要校验失败：预期 %s=%s，实际 %s", fileName, checkMethod, expected, actual));\n        }\n    }\n\n    /**\n     * 字符串参数解析：resolve 求值后统一转 String。\n     */\n    private String resolveStr(Object input) {\n        if (input == null) {\n            return null;\n        }\n        Object resolved = resolveParam(input);\n        return resolved == null ? null : resolved.toString();\n    }\n\n    private static String strOf(Object value) {\n        return value == null ? "" : value.toString();\n    }\n\n    private static String blankToNull(String value) {\n        return isBlank(value) ? null : value;\n    }\n\n    private static boolean isBlank(String value) {\n        return value == null || value.isBlank();\n    }\n\n    /**\n     * FILE_UPLOAD 组件（fileUpload）的节点参数。\n     * <pre>\n     * {\n     *   "connectionId": "bpm-default",              // 必填，BPM 连接实例\n     *   "sourcePath": "{{ $.request.files }}",       // 必填，要数据表达式，求值文件数组\n     *   "boId": "{{ $.boCreate1.boId }}",            // 必填，目标 BO 记录 ID（表达式/字面量）\n     *   "appId": "com.awspaas.user.apps.demo",      // 必填\n     *   "boName": "BO_DEMO_MAIN",                   // 必填\n     *   "boItemName": "BO_FIELD_FILE",              // 必填，附件字段名\n     *   "processInstId": "{{ $.processStart1.processInstanceId }}", // 可选\n     *   "taskInstId": "",                           // 可选\n     *   "validateChecksum": true                    // 可选，true 时每个文件必须携带 checkMethod+checksum\n     * }\n     * </pre>\n     *\n     * <p>sourcePath 数组每项：fileName/fileContent(base64) 必填，securityLevel/fileSize 可选，\n     * 可选 checkMethod(md5/sha1/sha256/sha512) + checksum(十六进制期望摘要)。\n     *\n     * <p>响应存 {@code $.<tag>.uploadedCount} 与 {@code $.<tag>.files}。\n     *\n     * @author databus\n     */\n    @Data\n    public static class FileUploadCfg {\n\n        /** 连接实例 ID（必填） */\n        @DatabusProp(label = "连接", required = true, widget = WidgetKind.CONNECTION_SELECT, order = 1)\n        private String connectionId;\n\n        /** 文件数组表达式（必填，要数据，{@code {{ $.路径 }}}） */\n        @DatabusProp(\n            label = "文件数组表达式", required = true, exprRole = ExprRole.DATA, order = 2,\n            placeholder = "{{ $.数据空间.files }}",\n            description = "求值结果为文件数组，每项含 fileName 与 base64 的 fileContent；常接 fileDownload 的输出"\n        )\n        private String sourcePath;\n\n        /** 目标 BO 记录 ID（必填，字面量或 {@code {{ $.路径 }}} 表达式） */\n        @DatabusProp(label = "目标 BO 记录 ID", required = true, exprRole = ExprRole.DATA, order = 3)\n        private String boId;\n\n        /** 应用 ID（必填） */\n        @DatabusProp(label = "应用 ID", required = true, order = 4, placeholder = "com.awspaas.user.apps.xxx")\n        private String appId;\n\n        /** BO 定义名（必填） */\n        @DatabusProp(label = "BO 定义名", required = true, order = 5, placeholder = "BO_XXX")\n        private String boName;\n\n        /** 附件字段名（必填） */\n        @DatabusProp(label = "附件字段名", required = true, order = 6, placeholder = "BO_FIELD_XXX")\n        private String boItemName;\n\n        /** 流程实例 ID（可选，字面量或 {@code {{ $.路径 }}} 表达式） */\n        @DatabusProp(label = "流程实例 ID", exprRole = ExprRole.DATA, order = 7)\n        private String processInstId;\n\n        /** 任务实例 ID（可选，字面量或 {@code {{ $.路径 }}} 表达式） */\n        @DatabusProp(label = "任务实例 ID", exprRole = ExprRole.DATA, order = 8)\n        private String taskInstId;\n\n        /** true 时要求每个文件都携带摘要校验信息，缺省 false */\n        @DatabusProp(\n            label = "校验文件摘要", widget = WidgetKind.BOOLEAN, order = 9,\n            description = "开启后每个文件必须携带 checkMethod（md5/sha1/sha256/sha512）与 checksum"\n        )\n        private Boolean validateChecksum;\n    }\n}\n', '初始迁移：内置 jar 件脚本化首版（seed 生成）', sysdate()),
    (1762000000001100018, 1762000000001000018, 1, 'java', 'package org.dromara.databus.script;\n\nimport lombok.extern.slf4j.Slf4j;\nimport org.dromara.common.core.exception.ServiceException;\nimport org.dromara.common.core.utils.SpringUtils;\nimport org.dromara.databus.component.DatabusNodeComponent;\nimport org.dromara.databus.component.schema.annotation.DatabusCmp;\nimport org.dromara.databus.connector.Connection;\nimport org.dromara.databus.connector.bpm.BpmHttpConnector;\nimport org.dromara.databus.connector.bpm.dto.FileDownloadRequest;\nimport java.util.Map;\nimport lombok.Data;\nimport org.dromara.databus.component.schema.annotation.DatabusProp;\nimport org.dromara.databus.component.schema.enums.ExprRole;\nimport org.dromara.databus.component.schema.enums.WidgetKind;\n\n\n\n\n/**\n * FILE_DOWNLOAD 组件（注册名 {@code fileDownload}）。\n *\n * <p>按 boId + fieldName 通过 BPM connector 读取 BO 记录附件字段的全部文件（base64），\n * 对应老系统 FileToBase64Processor（旧命名方向相反）。\n *\n * <p>响应存 {@code $.<tag>.fileCount} 与 {@code $.<tag>.files}；\n * files 可直接作为 fileUpload 的 sourcePath，附件搬运链无需中间转换。\n *\n * @author databus\n */\n@Slf4j\n@DatabusCmp(\n    code = "fileDownload", name = "BPM 下载附件", shortName = "下载附件",\n    icon = "ph:download-simple", color = "#0369a1",\n    description = "按 boId + 附件字段名读取 BO 记录全部文件转 base64，结果存 $.数据空间.files（可直接接上传组件）", sort = 210,\n    dataExample = """\n        {"connectionId":"bpm-default","boId":"{{ $.boCreate1.boResults[0].records[0].ID }}","fieldName":"BO_FIELD_FILE"}\n        """\n)\npublic class FileDownloadComponent extends DatabusNodeComponent {\n\n    @Override\n    public void process() {\n        FileDownloadCfg cfg = this.getCmpData(FileDownloadCfg.class);\n        if (cfg == null) {\n            throw new ServiceException("FILE_DOWNLOAD 组件缺少参数配置（tag=" + this.getTag() + "）");\n        }\n        String tag = this.getTag();\n        if (tag == null || tag.isBlank()) {\n            throw new ServiceException("FILE_DOWNLOAD 组件缺少数据空间标识（tag）");\n        }\n        String boId = resolveStr(cfg.getBoId());\n        String fieldName = resolveStr(cfg.getFieldName());\n        if (isBlank(cfg.getConnectionId()) || isBlank(boId) || isBlank(fieldName)) {\n            throw new ServiceException("FILE_DOWNLOAD 组件缺少 connectionId / boId / fieldName 配置（tag=" + tag + "）");\n        }\n\n        FileDownloadRequest request = new FileDownloadRequest();\n        request.setBoId(boId);\n        request.setFieldName(fieldName);\n\n        BpmHttpConnector connector = SpringUtils.getBean(BpmHttpConnector.class);\n        Connection conn = getDatabusContext().getConnection(resolveStr(cfg.getConnectionId()));\n\n        Object result = connector.fileDownload(conn, request);\n        if (!(result instanceof Map<?, ?> resultMap)) {\n            throw new ServiceException("FILE_DOWNLOAD 响应非 JSON 对象: " + result);\n        }\n        Object fileCount = resultMap.get("fileCount");\n        save("$." + tag + ".fileCount", fileCount);\n        save("$." + tag + ".files", resultMap.get("files"));\n\n        int count = fileCount instanceof Number number ? number.intValue() : 0;\n        resultSummary(count == 0 ? "下载 0 个附件（字段无文件）" : "下载 " + count + " 个附件");\n        log.info("[databus] fileDownload 完成 tag={} count={}", tag, count);\n    }\n\n    /**\n     * 字符串参数解析：resolve 求值后统一转 String。\n     */\n    private String resolveStr(Object input) {\n        if (input == null) {\n            return null;\n        }\n        Object resolved = resolveParam(input);\n        return resolved == null ? null : resolved.toString();\n    }\n\n    private static boolean isBlank(String value) {\n        return value == null || value.isBlank();\n    }\n\n    /**\n     * FILE_DOWNLOAD 组件（fileDownload）的节点参数。\n     * <pre>\n     * {\n     *   "connectionId": "bpm-default",       // 必填，BPM 连接实例\n     *   "boId": "{{ $.boCreate1.boId }}",        // 必填，BO 记录 ID（表达式/字面量）\n     *   "fieldName": "BO_FIELD_FILE"         // 必填，附件字段名（字面量）\n     * }\n     * </pre>\n     *\n     * <p>响应存 {@code $.<tag>.fileCount} 与 {@code $.<tag>.files}\n     * （含 base64 的完整文件列表，可直接作为 fileUpload 的 sourcePath 输入）。\n     *\n     * @author databus\n     */\n    @Data\n    public static class FileDownloadCfg {\n\n        /** 连接实例 ID（必填） */\n        @DatabusProp(label = "连接", required = true, widget = WidgetKind.CONNECTION_SELECT, order = 1)\n        private String connectionId;\n\n        /** BO 记录 ID（必填，字面量或 {@code {{ $.路径 }}} 表达式） */\n        @DatabusProp(\n            label = "BO 记录 ID", required = true, exprRole = ExprRole.DATA, order = 2,\n            placeholder = "{{ $.boCreate1.boId }}"\n        )\n        private String boId;\n\n        /** 附件字段名（必填，字面量） */\n        @DatabusProp(label = "附件字段名", required = true, order = 3, placeholder = "BO_FIELD_XXX")\n        private String fieldName;\n    }\n}\n', '初始迁移：内置 jar 件脚本化首版（seed 生成）', sysdate());
